nt:center;box-shadow:0 1px 3px var(--t-glow,rgba(0,0,0,.15))}\n</style>\n</head>\n<body>\n<textarea class=\"sbh-data-container\" type=\"text/plain\">$1</textarea>\n<div class=\"cs-wrap\"><div class=\"cs-root\" id=\"csRoot\">\n  <div class=\"cs-head\" id=\"csHead\">\n    <div class=\"cs-head-left\">\n      <span class=\"cs-fold-ind\" id=\"csFoldInd\">▾</span>\n      <span class=\"cs-head-title\">状态栏助手</span>\n      <span class=\"cs-head-sub\">后宫 · 生理监测</span>\n    </div>\n    <div class=\"cs-head-right\">\n      <span class=\"cs-theme-tag\" id=\"csThemeTag\">樱粉后宫</span>\n      <span class=\"cs-theme-btn\" id=\"csThemeBtn\" title=\"切换主题\">🎨</span>\n    </div>\n  </div>\n  <div class=\"cs-stage\"><div class=\"cs-scroll\" id=\"csScroll\"></div></div>\n</div></div>\n<\x73cript>\n/*SBH-v2.7*/\ntry{(function(){\nvar dataEl=document.querySelector('.sbh-data-container');\nvar rootEl=document.getElementById('csRoot');\nvar scrollEl=document.getElementById('csScroll');\nvar headEl=document.getElementById('csHead');\nvar themeTagEl=document.getElementById('csThemeTag');\nvar themeBtnEl=document.getElementById('csThemeBtn');\nif(!dataEl||!rootEl||!scrollEl)return;\nvar rawText=(dataEl.textContent||'').replace(/<br\\s*\\/?>/gi,'\\n');\nvar sel=null,prevSel=null,foldInfo=false,foldNames=false,foldPhy=false;\n/* 整体折叠状态（v3 风格：localStorage 记忆，默认展开） */\nvar OPEN_KEY='statusbar_fusion_body_open';\nvar bodyFold=false;\ntry{bodyFold=localStorage.getItem(OPEN_KEY)==='0';}catch(e){}\n\n/* ==================== 主题（v3：六主题，默认樱粉；--t-text 主文字色，--t-glow 柔和阴影色） ==================== */\nvar THEMES=[\n{name:'樱粉后宫',t:{'--t-bg1':'#faf3f6','--t-bg2':'#f3e7ec','--t-border':'#ead9e1','--t-border2':'#e5c9d8','--t-card':'#ffffff','--t-card2':'#f7eef2','--t-elev':'#fdf6f9','--t-text':'#4a3540','--t-dim':'#9a7d8b','--t-track':'#f0e4ea','--t-shadow':'#eed7e2','--t-glow':'rgba(190,90,130,.12)','--t-accent':'#cf668a'}},\n{name:'柔白医疗',t:{'--t-bg1':'#fbfcff','--t-bg2':'#f3f5fb','--t-border':'#e6e8ee','--t-border2