* 从文本提取最终值（取→后的数字） */\nfunction grabNum(raw,key){\n  var re=new RegExp(key+'[^：:]*[：:]\\\\s*(?:\\\\d+\\\\s*[→›>-]+\\\\s*)?(\\\\d+)','i');\n  var m=raw.match(re);\n  return m?parseInt(m[1],10):null;\n}\nfunction grabDelta(raw,key){\n  var re=new RegExp(key+'[^：:]*[：:]\\\\s*(\\\\d+\\\\s*[→›>-]+\\\\s*\\\\d+)(?:\\\\s*[（(]([^)）]*)[)）])?','i');\n  var m=raw.match(re);\n  if(!m)return'';\n  return m[1].trim()+(m[2]?' · '+m[2].trim():'');\n}\n/* 百分比数值 */\nfunction extractPercent(text){\n  var m=String(text||'').match(/(\\d+(?:\\.\\d+)?)\\s*%/);\n  if(!m)return null;\n  var n=parseFloat(m[1]);\n  return isNaN(n)?null:Math.max(0,Math.min(100,n));\n}\nfunction parseTriple(v){\n  var arr=String(v||'').split(/[|｜]/).map(function(s){return s.trim()});\n  return [arr[0]||'',arr[1]||'',arr[2]||''];\n}\nfunction splitProgress(desc){\n  var arr=String(desc||'').split(/[|｜]/).map(function(s){return s.trim()}).filter(Boolean);\n  return {phase:arr[0]||'监测中',sub:arr.slice(1).join(' | ')};\n}\n\n/* ==================== 全局信息 ==================== */\nfunction grabGlobal(raw){\n  var out={time:'',loc:'',task:''};\n  var secs=parseSections(raw);\n  for(var i=0;i<secs.length;i++){\n    if(/场景|概况/.test(secs[i].name)){\n      var kv=parseKV(secs[i].body);\n      for(var j=0;j<kv.length;j++){\n        if(!out.time&&kv[j].k==='时间'&&kv[j].raw.indexOf('{{')<0)out.time=kv[j].v;\n        if(!out.loc&&kv[j].k==='地点'&&kv[j].raw.indexOf('{{')<0)out.loc=kv[j].v;\n      }\n    }\n    if(!out.task&&/任务|目标/.test(secs[i].name)){\n      var kv2=parseKV(secs[i].body);\n      if(kv2.length&&kv2[0].raw.indexOf('{{')<0)out.task=kv2[0].v;\n    }\n  }\n  if(!out.task){var mt=raw.match(/主要任务[：:]\\s*([^\\n]+)/);if(mt&&mt[1].indexOf('{{')<0)out.task=mt[1].replace(/\\{\\{|\\}\\}/g,'').trim();}\n  if(!out.time){var mt2=raw.match(/^时间[：:]\\s*([^\\n]+)/m);if(mt2&&mt2[1].indexOf('{{')<0)out.time=mt2[1].replace(/\\{\\{|\\}\\}/g,'').trim();}\n  if(!out.loc){var mt3=raw.match(/^地点[：:]\\s*([^\\n]+)/m);if(mt3&&mt3[1].indexOf('{{')<0)out.loc=mt3[1].replace(/\\{\\{|\\}\\}/g,'').trim();}\n  return out;\n}\n\n/* ==================== 角色解析（新格式：<role_name=\"名字\"> 单块，生理数据在 [生理健康监测] 区块内） ==================== */\nfunction parseRoleBlocks(raw){\n  var blocks=[],re=/(?:<role_name=\"([^\"]+)\">|<role(\\d+)>)([\\s\\S]*?)<\\/(?:role_name|role\\d+|role)>/g,m;\n  while((m=re.exec(String(raw||'')))){\n    var name=m[1]?m[1].trim():(m[2]?('角色'+m[2]):'角色');\n    if(!name)continue;\n    blocks.push({name:name,raw:m[3]||''});\n  }\n  return blocks;\n}\nfunction roleName(b){\n  var rawName=b&&b.name?String(b.name).trim():'';\n  if(!rawName||rawName.indexOf('{{')>=0)return '角色';\n  return rawName.slice(0,12);\n}\nfunction roleTag(b){\n  var secs=parseSections(b.raw);\n  for(var i=0;i<secs.length;i++){\n    if(/身份/.test(secs[i].name)){\n      var kv=parseKV(secs[i].body);\n      for(var j=0;j<kv.length;j++)if(/状态/.test(kv[j].k)&&kv[j].v&&kv[j].raw.indexOf('{{')<0)return kv[j].v;\n    }\n  }\n  return'';\n}\n\n/* 从单个 role 块的 [生理健康监测] 区块解析生理数据（键: 值 行；兼容闭合/未闭合区块），解析失败返回 null */\nfunction parsePhyFromRole(role){\n  if(!role||!role.raw)return null;\n  var secs=parseSections(role.raw);\n  var phy=null;\n  for(var i=0;i<secs.length;i++){\n    if(/生理健康监测/.test(secs[i].name)){phy=secs[i];break;}\n  }\n  if(!phy)return null;\n  var body=phy.body;\n  var map={},lines=body.split(/\\r?\\n/);\n  for(var i=0;i<lines.length;i++){\n    var lm=lines[i].match(/^\\s*([^：:]+)\\s*[：:]\\s*(.*)$/);\n    if(lm&&lm[1].trim())map[lm[1].trim()]=lm[2].trim();\n  }\n  var pr=splitProgress(map['进度描述']);\n  var stage=(map['生理阶段']&&map['生理阶段'].trim())?map['生理阶段'].trim():pr.phase;\n  var d1=parseTriple(map['数据项一']),d2=parseTriple(map['数据项二']);\n  var d3=parseTriple(map['数据项三']),d4=parseTriple(map['数据项四']);\n  var rows=[parseTriple(map['状态条一']),parseTriple(map['状态条二']),parseTriple(map['状态条三'])];\n  var percent=(extractPercent(d2[1])!==null&&extractPercent(d2[1])!==void 0?extractPercent(d2[1]):(extractPercent(d1[1])!==null&&extractPercent(d1[1])!==void 0?extractPercent(d1[1]):(extractPercent(map['计算说明'])!==null&&extractPercent(map['计算说明'])!==void 0?extractPercent(map['计算说明']):0)));\n  return {\n    name:roleName(role),\n    title:map['状态标题']||'状态监测',\n    phase:stage,sub:pr.sub,\n    minor:map['次要描述']||'',\n    calc:map['计算说明']||'',\n    d1:d1,d2:d2,d3:d3,d4:d4,rows:rows,percent:percent,\n  };\n}\n/* 从 <status_profile> 块解析生理数据（旧格式数据兜底，渲染旧楼层仍可用） */\nfunction parseProfileFromLegacy(raw){\n  var list=[],re=/<status_profile\\s+name=\"([^\"]+)\">([\\s\\S]*?)<\\/status_profile>/g,m;\n  while((m=re.exec(String(raw||'')))!==null){\n    var map={},lines=(m[2]||'').split(/\\r?\\n/);\n    for(var i=0;i<lines.length;i++){\n      var lm=lines[i].match(/^\\s*([^：:]+)\\s*[：:]\\s*(.*)$/);\n      if(lm&&lm[1].trim())map[lm[1].trim()]=lm[2].trim();\n    }\n    var pr=splitProgress(map['进度描述']);\n    var d1=parseTriple(map['数据项一']),d2=parseTriple(map['数据项二']);\n    var d3=parseTriple(map['数据项三']),d4=parseTriple(map['数据项四']);\n    var rows=[parseTriple(map['状态条一']),parseTriple(map['状态条二']),parseTriple(map['状态条三'])];\n    list.push({\n      name:m[1].trim(),\n      title:map['状态标题']||'状态监测',\n      phase:pr.phase,sub:pr.sub,\n      minor:map['次要描述']||'',\n      calc:map['计算说明']||'',\n      d1:d1,d2:d2,d3:d3,d4:d4,rows:rows,\n      percent:(extractPercent(d2[1])!==null&&extractPercent(d2[1])!==void 0?extractPercent(d2[1]):(extractPercent(d1[1])!==null&&extractPercent(d1[1])!==void 0?extractPercent(d1[1]):(extractPercent(map['计算说明'])!==null&&extractPercent(map['计算说明'])!==void 0?extractPercent(map['计算说明']):0))),\n    });\n  }\n  return list;\n}\n/* 生理数据主来源：每个 role 块的 [生理健康监测] 区块；旧 <status_profile> 块兜底 */\nfunction parsePhys(raw,roleBlocks){\n  var list=[];\n  for(var i=0;i<roleBlocks.length;i++){\n    var p=parsePhyFromRole(roleBlocks[i]);\n    if(p)list.push(p);\n  }\n  if(!list.length)list=parseProfileFromLegacy(raw);\n  return list;\n}\n/* 全部后宫名单：优先 [后宫名单] 区块，否则回退 role_name 属性名 */\nfunction grabHarem(raw,roleBlocks,profs){\n  var out=[];\n  var m=raw.match(/\\[后宫名单\\]([\\s\\S]*?)\\[\\/后宫名单\\]/);\n  if(m){\n    var lines=m[1].split(/\\n+/);\n    for(var i=0;i<lines.length;i++){\n      var l=lines[i].replace(/^[\\s\\-•·\\d\\.、]+/,'').split(/[：:]/)[0].trim();\n      if(!l||l.indexOf('{{')>=0)continue;\n      var parts=l.split(/[、，,]/);\n      for(var j=0;j<parts.length;j++){\n        var p=parts[j].replace(/^[\\s\\-•·\\d\\.、]+/,'').trim();\n        if(p&&p.indexOf('{{')<0&&out.indexOf(p)<0)out.push(p.slice(0,12));\n      }\n    }\n  }\n  if(!out.length){for(var k=0;k<roleBlocks.length;k++)out.push(roleName(roleBlocks[k]));}\n  if(!out.length&&profs){for(var p=0;p<profs.length;p++){var pn=profs[p].name;if(pn&&out.indexOf(pn)<0)out.push(pn.slice(0,12));}}\n  return out;\n}\n/* 名字 → role 块 / 生理数据 匹配 */\nfunction matchByName(name,list,getNameFn){\n  var i,n;\n  /* 第一轮：精确匹配优先（避免「苏媚」前缀误配「苏媚娘」等名字包含关系） */\n  for(i=0;i<list.length;i++){\n    n=getNameFn(list[i]);\n    if(n===name)return i;\n  }\n  /* 第二轮：前缀/包含匹配兜底（兼容 AI 在 role_name 里写全名/称号） */\n  for(i=0;i<list.length;i++){\n    n=getNameFn(list[i]);\n    if(n.indexOf(name)===0||name.indexOf(n)===0)return i;\n  }\n  return -1;\n}\n/* 阶段判色（v3） */\nfunction titleEmoji(t){if(/绝经/.test(t))return'🕯️';if(/孕期|妊娠/.test(t))return'🌟';if(/恶露/.test(t))return'🩸';if(/哺乳/.test(t))return'🤱';if(/周期/.test(t))return'🌙';return'🌡️';}\nfunction phaseColor(phase){\n  var t=String(phase||'').trim();\n  if(/绝经/.test(t))return{a:'#8a8f98',b:'#b9bec6'};\n  if(/恶露/.test(t))return{a:'#b9572f',b:'#e08a5a'};\n  if(/哺乳/.test(t))return{a:'#c46aa8',b:'#e8a5d0'};\n  if(/孕早期|孕中期|孕晚期|妊娠|孕/.test(t))return{a:'#d68910',b:'#ff4fa3'};\n  if(/排卵/.test(t))return{a:'#ff4d85',b:'#ff8fb3'};\n  if(/黄体/.test(t))return{a:'#1fa37a',b:'#6ad9a7'};\n  if(/卵泡/.test(t))return{a:'#6c5ce7',b:'#9fa8da'};\n  if(/月经|经期/.test(t))return{a:'#c62828',b:'#e57373'};\n  return{a:'var(--t-accent)',b:'var(--t-accent)'};\n}\n\n/* ==================== 渲染 ==================== */\nfunction barHTML(label,v,colorFn){\n  var html='<div class=\"cs-d-bar\"><span class=\"cs-d-bl\">'+esc(label)+'</span>';\n  if(v===null){html+='<div class=\"cs-d-track\" style=\"flex:1\"></div><span class=\"cs-d-num\" style=\"color:var(--t-dim,#a89099)\">未知</span>';}\n  else{html+='<div class=\"cs-d-track\"><span class=\"cs-d-fill\" style=\"width:'+Math.max(2,v)+'%;background:'+colorFn(v)+'\"></span></div><span class=\"cs-d-num\">'+v+'/100</span>';}\n  html+='</div>';\n  return html;\n}\nfunction affColor(v){if(v>=80)return'#e8a93c';if(v>=50)return'#5bb89a';return'#5b9bd5'}\nfunction lustColor(v){if(v>=90)return'#b83360';if(v>=70)return'#cf668a';if(v>=40)return'#e8a5bc';return'#f0c8d4'}\n\nfunction overviewHTML(roles,profs,harem,g){\n  var html='<div class=\"cs-overview\">';\n  for(var i=0;i<harem.length;i++){\n    var name=harem[i];\n    var ri=matchByName(name,roles,roleName);\n    var pi=matchByName(name,profs,function(p){return p.name});\n    var role=ri<0?null:roles[ri];\n    var prof=pi<0?null:profs[pi];\n    var c=prof?phaseColor(prof.phase):{a:'var(--t-accent)',b:'var(--t-accent)'};\n    var aff=role?grabNum(role.raw,'好感'):null;\n    var lus=role?grabNum(role.raw,'性欲'):null;\n    var tag=(role?roleTag(role):'')||(ri<0?'暂无状态':'');\n    var age=role?grabNum(role.raw,'年龄'):null;\n    var mini='';\n    if(aff!==null)mini+='<div class=\"cs-o-bar\"><span class=\"cs-o-bl\">好感</span><span class=\"cs-o-track\"><span class=\"cs-o-fill\" style=\"width:'+Math.max(2,aff)+'%;background:'+affColor(aff)+'\"></span></span><span class=\"cs-o-num\">'+aff+'</span></div>';\n    if(lus!==null)mini+='<div class=\"cs-o-bar\"><span class=\"cs-o-bl\">性欲</span><span class=\"cs-o-track\"><span class=\"cs-o-fill\" style=\"width:'+Math.max(2,lus)+'%;background:'+lustColor(lus)+'\"></span></span><span class=\"cs-o-num\">'+lus+'</span></div>';\n    if(prof!==null&&!(/绝经|孕期|恶露/.test(prof.phase||\"\")))mini+='<div class=\"cs-o-bar\"><span class=\"cs-o-bl\">受孕</span><span class=\"cs-o-track\"><span class=\"cs-o-fill\" style=\"width:'+Math.max(2,prof.percent)+'%;background:'+c.a+'\"></span></span><span class=\"cs-o-num\">'+prof.percent+'%</span></div>';\n    html+='<div class=\"cs-o-card\" data-i=\"'+i+'\"><span class=\"cs-o-av\" style=\"background:linear-gradient(135deg,'+c.a+','+c.b+')\">'+esc(name.charAt(0))+'</span><span class=\"cs-o-mid\"><span class=\"cs-o-head\"><span class=\"cs-o-name\">'+esc(name)+'</span>'+(age!=null?'<span class=\"cs-o-tag\">'+age+'岁</span>':'')+(prof?'<span class=\"cs-o-phase\">'+esc(prof.phase)+'</span>':'')+(tag?'<span class=\"cs-o-tag cs-o-state\">'+esc(tag)+'</span>':'')+'</span><span class=\"cs-o-bars\">'+mini+'</span></span><span class=\"cs-o-go\">›</span></div>';\n  }\n  html+='</div>';\n  return html;\n}\n\nfunction phyHTML(prof,c){\n  if(!prof)return'';\n  var html='<div class=\"cs-phy'+(foldPhy?' cs-phy-fold':'')+'\">'\n    +'<div class=\"cs-phy-head\">'+titleEmoji(prof.title||'')+' '+esc(prof.title||'状态监测')+(prof.sub?' · '+esc(prof.sub):'')+'<span class=\"cs-phy-chev\">▸</span></div>'\n    +'<div class=\"cs-phy-body\">';\n  var metric='<div class=\"cs-metric-grid\">';\n  metric+='<div class=\"cs-metric\"><div class=\"cs-metric-k\">'+esc(prof.d1[0]||'数据项一')+'</div><div class=\"cs-metric-v\">'+esc(prof.d1[1]||'-')+'</div></div>';\n  metric+='<div class=\"cs-metric\"><div class=\"cs-metric-k\">'+esc(prof.d2[0]||'数据项二')+'</div><div class=\"cs-metric-v hl\">'+esc(prof.d2[1]||'-')+'</div></div>';\n  if(prof.d3&&prof.d3[0])metric+='<div class=\"cs-metric\"><div class=\"cs-metric-k\">'+esc(prof.d3[0])+'</div><div class=\"cs-metric-v\">'+esc(prof.d3[1]||'-')+'</div></div>';\n  if(prof.d4&&prof.d4[0])metric+='<div class=\"cs-metric\"><div class=\"cs-metric-k\">'+esc(prof.d4[0])+'</div><div class=\"cs-metric-v hl\">'+esc(prof.d4[1]||'-')+'</div></div>';\n  metric+='</div>';\n  html+=metric;\n  var showRisk=!(/绝经|孕期|恶露/.test(prof.phase||\"\"))&&prof.percent>=0;if(showRisk)html+='<div class=\"cs-phy-progress\"><div class=\"cs-phy-plabel\"><span>累计受孕率</span><span style=\"color:'+c.a+'\">'+prof.percent+'%</span></div><div class=\"cs-phy-track\"><div class=\"cs-phy-fill\" style=\"width:'+Math.max(2,prof.percent)+'%;background:linear-gradient(90deg,'+c.a+','+c.b+')\"></div></div></div>';\n  if(prof.minor)html+='<div class=\"cs-phy-progress\" style=\"margin-top:8px;font-size:11.5px;line-height:1.5;background:var(--t-elev);border:1px solid var(--t-border2);border-radius:10px;padding:7px 10px\"><b style=\"color:'+c.a+'\">附加：</b>'+nl2br(prof.minor)+'</div>';\n  if(prof.calc)html+='<div class=\"cs-phy-calc\"><details><summary>🎲 逻辑与计算推演</summary><div class=\"cs-phy-calc-content\">'+nl2br(prof.calc)+'</div></details></div>';\n  var rows=prof.rows.filter(function(r){return r[0]||r[1]||r[2]});\n  if(rows.length){html+='<div class=\"cs-phy-rows\">'+rows.map(function(r){return'<div class=\"cs-row\"><div class=\"cs-row-icon\">'+esc(r[0]||'•')+'</div><div class=\"cs-row-main\"><div class=\"cs-row-k\">'+esc(r[1]||'状态条')+'</div><div class=\"cs-row-v\">'+nl2br(r[2]||'-')+'</div></div></div>'}).join('')+'</div>';}\n  html+='</div></div>';\n  return html;\n}\n\nfunction roleSectionsHTML(role){\n  if(!role)return'';\n  var secs=parseSections(role.raw);\n  var html='';\n  for(var i=0;i<secs.length;i++){\n    if(/场景|概况|任务|目标|生理健康监测/.test(secs[i].name))continue; // 生理监测是卡主体，单独渲染\n    var kv=parseKV(secs[i].body);\n    if(!kv.length)continue;\n    html+='<details class=\"cs-sec\" open><summary>'+esc(secs[i].name)+'</summary><div class=\"cs-sec-body\">';\n    for(var j=0;j<kv.length;j++)html+='<div class=\"cs-kv\"><span class=\"cs-k\">'+esc(kv[j].k)+'</span><span class=\"cs-v\">'+esc(kv[j].v)+'</span></div>';\n    html+='</div></details>';\n  }\n  return html;\n}\n\nfunction detailHTML(roles,profs,harem,i){\n  var name=harem[i];\n  var ri=matchByName(name,roles,roleName);\n  var pi=matchByName(name,profs,function(p){return p.name});\n  var role=ri<0?null:roles[ri];\n  var prof=pi<0?null:profs[pi];\n  var c=prof?phaseColor(prof.phase):{a:'var(--t-accent)',b:'var(--t-accent)'};\n  var aff=role?grabNum(role.raw,'好感'):null;\n  var lus=role?grabNum(role.raw,'性欲'):null;\n  var age=role?grabNum(role.raw,'年龄'):null;\n  var exp=role?grabNum(role.raw,'经验次数'):null;\n  var affD=role?grabDelta(role.raw,'好感'):'';\n  var lusD=role?grabDelta(role.raw,'性欲'):'';\n  var tag=role?roleTag(role):'';\n  var html='<div class=\"cs-d-head\"><span class=\"cs-d-av\" style=\"background:linear-gradient(135deg,'+c.a+','+c.b+')\">'+esc(name.charAt(0))+'</span><span class=\"cs-d-mid\" style=\"flex:1 1 0;min-width:0;display:flex;align-items:center;gap:6px;flex-wrap:wrap\"><span class=\"cs-d-name\" style=\"white-space:nowrap\">'+esc(name)+'</span>'+(age!=null?'<span class=\"cs-d-tag\">'+age+'岁</span>':'')+(exp!=null?'<span class=\"cs-d-tag\">经验 '+exp+' 次</span>':'')+(prof?'<span class=\"cs-d-phase\">'+esc(prof.phase)+'</span>':'')+'</span>'+(tag?'<div class=\"cs-d-state\">当前状态：'+esc(tag)+'</div>':'');\n  if(aff!==null||lus!==null){\n    html+='<div class=\"cs-d-extra\">';\n    html+=barHTML('好感度',aff,affColor)+(affD?'<div style=\"font-size:10.5px;color:#a89099;font-weight:600;padding-left:58px;margin-top:-3px\">'+esc(affD)+'</div>':'');\n    html+=barHTML('性欲值',lus,lustColor)+(lusD?'<div style=\"font-size:10.5px;color:#a89099;font-weight:600;padding-left:58px;margin-top:-3px\">'+esc(lusD)+'</div>':'');\n    html+='</div>';\n  }\n  html+='</div>';\n  if(!role&&!prof){html+='<div class=\"cs-empty\">该成员本次未生成状态栏，仅 '+harem.length+' 位成员输出了详细数据。</div>';return html;}\n  html+=phyHTML(prof,c);\n  html+=roleSectionsHTML(role);\n  return html;\n}\n\n/* ==================== 主渲染 ==================== */\nfunction render(){\n  if(sel!==null&&prevSel===null){foldInfo=true;foldNames=true;}\n  else if(sel===null&&prevSel!==null){foldInfo=false;foldNames=false;}\n  prevSel=sel;\n  if(rootEl){rootEl.classList.toggle('cs-fold-info',foldInfo);rootEl.classList.toggle('cs-fold-names',foldNames);}\n\n  var roleBlocks=parseRoleBlocks(rawText);\n  var profs=parsePhys(rawText,roleBl