ength+'</b> 位</span><span class=\"cs-tb-hint\">'+((sel===null)?'左右滑动切换':curName)+'</span><span class=\"cs-tb-chev\">▸</span></div><div class=\"cs-names-body\"><div class=\"cs-chips\">';\n    for(var k=0;k<harem.length;k++){\n      var pi=matchByName(harem[k],profs,function(p){return p.name});\n      var pc=pi>=0?phaseColor(profs[pi].phase):{a:'var(--t-accent)',b:'var(--t-accent)'};\n      chips+='<span class=\"cs-chip'+(sel===k?' active':'')+'\" data-i=\"'+k+'\" style=\"'+(sel===k?'background:linear-gradient(135deg,'+pc.a+','+pc.b+');border-color:'+pc.a:'' )+'\"><span class=\"cs-c-av\">'+esc(harem[k].charAt(0))+'</span>'+esc(harem[k])+'</span>';\n    }\n    chips+='</div></div>';\n    chipsHtml='<div class=\"cs-names\">'+chips+'</div>';\n  }\n\n  /* 全部内容写进同一个滚动流：向下滚动时 场景信息 / 后宫成员 / 内容 一起滑动 */\n  scrollEl.innerHTML=topHtml+chipsHtml+contentHtml;\n\n  /* 事件绑定 */\n  var cards=scrollEl.querySelectorAll('.cs-o-card');\n  for(var j=0;j<cards.length;j++)cards[j].addEventListener('click',function(){var n=parseInt(this.getAttribute('data-i'),10);sel=(sel===n)?null:n;render()});\n  var chipsEls=scrollEl.querySelectorAll('.cs-chip');\n  for(var q=0;q<chipsEls.length;q++)chipsEls[q].addEventListener('click',function(){var n=parseInt(this.getAttribute('data-i'),10);sel=(sel===n)?null:n;render()});\n  bindBar('csTopBar','cs-fold-info');\n  bindBar('csNamesBar','cs-fold-names');\n  /* 生理监测卡：点渐变标题条收缩/展开（foldPhy 记忆，切换角色/重渲染后保持） */\n  var phyHeads=scrollEl.querySelectorAll('.cs-phy-head');\n  for(var h=0;h<phyHeads.length;h++)phyHeads[h].addEventListener('click',function(){\n    foldPhy=!foldPhy;\n    var pcs=scrollEl.querySelectorAll('.cs-phy');\n    for(var z=0;z<pcs.length;z++)pcs[z].classList.toggle('cs-phy-fold',foldPhy);\n  });\n}\n\nfunction bindBar(id,cls){\n  var bar=document.getElementById(id);\n  if(bar)bar.addEventListener('click',function(){\n    var f=cls==='cs-fold-info'?foldInfo:foldNames;\n    if(cls==='cs-fold-info')foldInfo=!f;else foldNames=!f;\n    if(rootEl)rootEl.classList.toggle(cls,cls==='cs-fold-info'?foldInfo:foldNames);\n  });\n}\n\nrender();\nsyncBodyFold();      // 应用保存的整体折叠状态\nbindHeadEvents();    // 头部：点标题区折叠/展开，点主题按钮/主题名循环主题\n\n/* 左右滑动切换成员（环回循环） */\nvar sX=null,sY=null,sA=false;\nfunction doSwipe(dx){\n  if(!scrollEl)return;\n  var harem=[];\n  var roleBlocks=parseRoleBlocks(rawText);\n  var profs=parsePhys(rawText,roleBlocks);\n  harem=grabHarem(rawText,roleBlocks,profs);\n  if(harem.length<2)return;\n  var cur=(sel===null)?(dx<0?-1:harem.length):sel;\n  var n=cur+(dx<0?1:-1);\n  if(n<0)n=harem.length-1;if(n>=harem.length)n=0;\n  sel=n;render();\n}\nscrollEl.addEventListener('pointerdown',function(e){if(!e.isPrimary)return;sX=e.clientX;sY=e.clientY;sA=true;});\nscrollEl.addEventListener('pointermove',function(e){\n  if(!sA||!e.isPrimary)return;\n  var dx=e.clientX-sX,dy=e.clientY-sY;\n  if(Math.abs(dy)>Math.abs(dx)*1.5&&Math.abs(dy)>10){sA=false;return;}\n  if(Math.abs(dx)>=60){sA=false;doSwipe(dx);}\n});\nscrollEl.addEventListener('pointerup',function(e){if(!sA)return;var dx=e.clientX-sX;sA=false;sX=null;sY=null;if(Math.abs(dx)>=60)doSwipe(dx);});\nscrollEl.addEventListener('pointercancel',function(){sA=false;});\n})();}catch(err){try{var _de=document.querySelector('.sbh-data-container'),_se=document.getElementById('csScroll');if(_se)_se.innerHTML='<div style=\"padding:18px 12px;color:#a89099;font-size:13px\">状态栏渲染失败(数据已保存,不影响正文): '+String(err&&err.message||err)+'</div>';}catch(_e2){}}\n<\/script>\n</body>\n</html>\n\n```","trim_strings":[],"source":{"user_input":false,"ai_output":true,"slash_command":false,"world_info":false,"reasoning":false},"destination":{"display":true,"prompt":false},"run_on_edit":true,"min_depth":null,"max_depth":5};;;;;;;

/** 确保渲染正则已安装（幂等）：
    - 全局/当前角色正则已存在（按 id 或名字）→ 跳过，尊重用户修改不覆盖；
    - force=true（面板「更新渲染正则」）→ 强制把全局正则里的同名项替换为内置版；
    - v2 已存在但内容不是内置最新版（缺单层实体兼容 / 缺 SBH 版本标记）→ 自动升级为内置版；
    - **v2 统一排在全局正则列表【最前】并清理旧版渲染正则**：
      SillyTavern 按列表顺序依次应用正则，若旧渲染正则（竖排详情头 / 带图 v3）残留且排在 v2 前面，
      会先把 <libido_status>/<status_profile> 替换成旧 HTML，v2 随后匹配不到 → 界面一直是老样式（详情头竖排）。
      v2 排最前 = 先命中先替换成横排融合终端，残留旧正则再跑已找不到状态栏标签，不会再覆盖成竖排。
    返回值: installed/updated/exists/no-api/error */
async function ensureRenderRegex(force) {
  try {
    const get = thFn('getTavernRegexes');
    const rep = thFn('replaceTavernRegexes');
    if (!get || !rep) {
      log('warn', '当前酒馆助手没有正则管理接口（getTavernRegexes/replaceTavernRegexes），无法自动安装渲染正则。请手动导入「多角色状态栏（方文制作）v2」正则，或升级酒馆助手。');
      try { toastr.warning('无法自动安装渲染正则：当前酒馆助手版本不支持正则接口，请手动导入'); } catch (e) {}
      return 'no-api';
    }
    // 全局 + 当前角色两个作用域都查（仅用于日志/判断 v2 是否已存在）
    let found = null;
    try {
      const g = get({ type: 'global' }) || [];
      found = g.find(r => r && (r.id === SBH_REGEX_ID || r.script_name === SBH_REGEX_NAME)) || null;
    } catch (e) {}
    if (!found) {
      try {
        const c = get({ type: 'character', name: 'current' }) || [];
        found = c.find(r => r && (r.id === SBH_REGEX_ID || r.script_name === SBH_REGEX_NAME)) || null;
      } catch (e) {}
    }
    // 清理旧版渲染正则【总是执行，不再因 v2 已存在而跳过】：
    // 旧版「多角色状态栏」「状态栏监测终端v3」「状态栏助手-融合终端」「多角色状态栏（方文制作）」等
    // 若残留于任意作用域，会抢先渲染成旧样式——必须每次都剔除；v2 本体始终保留。
    const isOld = function (r) {
      if (!r) return true;
      if (r.id === SBH_REGEX_ID || r.script_name === SBH_REGEX_NAME) return false; // v2 本体保留
      if ((SBH_LEGACY_REGEX_IDS || []).indexOf(r.id) >= 0) return true;
      if ((SBH_LEGACY_REGEX_NAMES || []).indexOf(r.script_name) >= 0) return true;
      return false;
    };
    // 全局：剔除旧版渲染正则；v2 内容过旧（缺单层实体兼容 / 缺 SBH-v2.7 版本标记）时自动升级为内置版；
    // v2 统一 unshift 到列表【最前】——SillyTavern 按列表顺序依次应用正则，v2 先命中先替换成横排融合终端，
    // 残留旧正则再运行时已找不到 <libido_status>/<status_profile> 标签，不会抢先渲染成竖排/带图老界面。
    const gList = get({ type: 'global' }) || [];
    const gKeep = gList.filter(r => !isOld(r));
    const gV2 = gKeep.find(r => r && r.id === SBH_REGEX_ID) || null;
    // v2 内容过旧判定：缺单层实体兼容 / 缺 SBH-v2.7 版本标记（随内置渲染 UI 结构升级递增），或渲染 JS 仍含 ES2020
    // 的 ?? 空值合并运算符（旧浏览器/WebView 解析失败 → 状态栏追加报错），都视为旧版并自动升级
    const v2Current = !!gV2 && !!gV2.find_regex && gV2.find_regex.indexOf('&lt;') >= 0
      && !!gV2.replace_string && gV2.replace_string.indexOf('SBH-v2.7') >= 0
      && gV2.replace_string.indexOf('??') < 0;
    const useBuiltin = !!force || !v2Current;
    const gOthers = gKeep.filter(r => r && r.id !== SBH_REGEX_ID);
    gOthers.unshift(useBuiltin ? JSON.parse(JSON.stringify(SBH_REGEX_DEF)) : gV2);
    const gChanged = useBuiltin || gOthers.length !== gList.length
      || JSON.stringify(gOthers.map(r => r && r.id)) !== JSON.stringify(gList.map(r => r && r.id));
    if (gChanged) await rep(gOthers, { type: 'global' });
    // 当前角色局部：剔除旧版（不追加新 def，渲染统一走全局；仅在确有旧正则时写卡）
    try {
      const cList = get({ type: 'character', name: 'current' }) || [];
      const cOthers = cList.filter(r => !isOld(r));
      if (cOthers.length !== cList.length) {
        await rep(cOthers, { type: 'character', name: 'current' });
        log('info', '已清理当前角色卡上的旧版渲染正则（' + (cList.length - cOthers.length) + ' 条）');
      }
    } catch (e) {
      log('warn', '清理角色局部正则失败（可忽略，全局正则已就绪）: ' + String(e && e.message || e));
    }
    if (!gChanged && !found) {
      // v2 已在全局（无变化）且未在角色局部找到 —— 已就绪
      log('info', '渲染正则「' + SBH_REGEX_NAME + '」已就绪（旧版渲染正则已清理）');
      try { toastr.info('状态栏助手：渲染正则已就绪，旧版渲染正则已清理'); } catch (e) {}
      return 'exists';
    }
    if (!gChanged) return 'exists'; // v2 存在且无内容变化 → 已就绪
    log('success', (found ? '已更新' : '已自动安装') + '渲染正则「' + SBH_REGEX_NAME + '」（全局共 ' + gOthers.length + ' 条，v2 已置顶，旧版渲染正则已同步清理）。含状态栏标签的楼层将自动渲染为横排融合终端。');
    try { toastr.success('状态栏助手：渲染正则已' + (found ? '更新' : '自动安装') + '（旧版渲染正则已替换）'); } catch (e) {}
    return found ? 'updated' : 'installed';
  } catch (e) {
    log('error', '安装/更新渲染正则失败: ' + String(e && e.stack || e));
    try { toastr.error('渲染正则安装失败，详情见日志（也可手动导入 多角色状态栏（方文制作）v2 正则）'); } catch (e2) {}
    return 'error';
  }
}

/* ==================== 世界书 / 对话收集 ==================== */

/** 最近一次正文生成时酒馆实际激活的世界书条目（WORLD_INFO_ACTIVATED 事件缓存）
    条目带 world(书名)/position(0-7)/order/content/constant/selective/key —— 激活已按酒馆规则完成 */
let lastActivated = [];

function onWorldInfoActivated(entries) {
  try {
    if (Array.isArray(entries)) lastActivated = entries;
  } catch (e) {}
}

/** 当前激活世界书列表（全局 + 角色 + 聊天，去重）。全部为同步接口 */
function getActiveWorldbooksSync() {
  const arr = [];
  const push = (name, source) => {
    if (name && !arr.some(x => x.name === name)) arr.push({ name: name, source: source });
  };
  try { (thFn('getGlobalWorldbookNames')() || []).forEach(n => push(n, '全局')); } catch (e) {}
  try {
    const c = thFn('getCharWorldbookNames')('current');
    if (c) {
      if (c.primary) push(c.primary, '角色主书');
      (c.additional || []).forEach(n => push(n, '角色附加'));
    }
  } catch (e) {}
  try { const ch = thFn('getChatWorldbookName')('current'); if (ch) push(ch, '聊天'); } catch (e) {}
  return arr;
}

/** 酒馆所有世界书名称（同步接口） */
function getWorldbookNamesSync() {
  try {
    const fn = thFn('getWorldbookNames');
    return fn ? (fn() || []) : [];
  } catch (e) {
    log('warn', '读取全部世界书列表失败: ' + String(e && e.message || e));
    return [];
  }
}

/** 新版 WorldbookEntry.position.type → 酒馆 position 数字（world_info_position 枚举） */
function posTypeToNum(type) {
  switch (type) {
    case 'before_character_definition': return 0; // before
    case 'after_character_definition': return 1;  // after
    case 'before_author_note': return 2;          // ANTop
    case 'after_author_note': return 3;           // ANBottom
    case 'at_depth': return 4;                    // atDepth
    case 'before_example_messages': return 5;     // EMTop
    case 'after_example_messages': return 6;      // EMBottom
    case 'outlet': return 7;                      // outlet
    default: return 0;
  }
}

/** 归一化条目为 { world, position(数字), order, depth, content, constant, selective, key } */
function normalizeEntry(en, worldName) {
  let pos = 0, order = 0, depth = 0;
  if (en.position && typeof en.position === 'object' && en.position.type) {
    pos = posTypeToNum(en.position.type);
    order = Number(en.position.order) || 0;
    depth = Number(en.position.depth) || 0;
  } else {
    pos = Number(en.position) || 0;
    order = Number(en.order) || 0;
    depth = Number(en.depth) || 0;
  }
  let keys = [];
  if (Array.isArray(en.key)) keys = en.key;
  else if (en.strategy && Array.isArray(en.strategy.keys)) keys = en.strategy.keys;
  return {
    world: worldName || (en.world || ''),
    position: pos,
    order: order,
    depth: depth,
    content: String(en.content || ''),
    constant: en.constant === true || (en.strategy && en.strategy.type === 'constant'),
    selective: en.selective === true || (en.strategy && en.strategy.type === 'selective'),
    keys: keys.map(k => String(k)),
  };
}

/** 按酒馆规则排序：before(0)/after(1) 组内按 order 升序；atDepth(4) 按 depth 升序、组内 order 升序；其余位置（AN/EM/outlet）不参与状态栏资料 */
function sortEntriesByST(entries) {
  const before = [], after = [], depth = [], ignored = [];
  entries.forEach(function (en) {
    if (en.position === 0) before.push(en);
    else if (en.position === 1) after.push(en);
    else if (en.position === 4) depth.push(en);
    else ignored.push(en);
  });
  before.sort((a, b) => a.order - b.order);
  after.sort((a, b) => a.order - b.order);
  depth.sort((a, b) => (a.depth - b.depth) || (a.order - b.order));
  return { before: before, after: after, depth: depth, ignored: ignored };
}

/** 把排序后的条目拼接成世界书文本 */
function joinSorted(byST) {
  const groups = [byST.before, byST.after, byST.depth];
  return groups.map(function (g) {
    return g.map(en => en.content.trim()).filter(Boolean).join('\n\n');
  }).filter(Boolean).join('\n\n');
}

/** 主路径：用「正文生成时酒馆实际激活的世界书条目」缓存 —— 激活已完全按酒馆规则完成，
    此处只做：① 剔除用户排除的书 ② 剔除格式类条目 ③ 按酒馆规则排序拼接 */
function collectWorldbookFromEvent(cfg) {
  const excluded = cfg.excluded_worldbooks || {};
  const cache = lastActivated || [];
  const mine = cache.filter(en => en && en.world && !excluded[en.world]
    && typeof en.content === 'string'
    && en.content.indexOf('<libido_status>') < 0
    && en.content.indexOf('<role_name="') < 0
    && en.content.indexOf('<status_profile') < 0);
  if (!mine.length) return { str: '', n: 0 };
  const byST = sortEntriesByST(mine.map(en => normalizeEntry(en, en.world)));
  const str = joinSorted(byST);
  const n = byST.before.length + byST.after.length + byST.depth.length;
  if (n) log('info', '世界书 [事件缓存·按酒馆规则] 参与 ' + n + ' 条（before ' + byST.before.length + ' / after ' + byST.after.length + ' / 深度 ' + byST.depth.length + (byST.ignored.length ? '，跳过其他位置 ' + byST.ignored.length + ' 条' : '') + '）');
  return { str: str, n: n };
}

/** 兜底：读激活书条目，模拟酒馆规则扫描 —— 蓝灯常驻全发 + 绿灯按最近对话关键字匹配 + 向量化跳过，再按酒馆规则排序 */
async function scanWorldbookFallback(cfg) {
  const excluded = cfg.excluded_worldbooks || {};
  const names = getActiveWorldbooksSync().map(w => w.name).filter(n => !excluded[n]);
  const chatText = getRecentChat(4).join('\n').toLowerCase();

  const all = [];
  for (const n of names) {
    try {
      const entries = await thFn('getWorldbook')(n);
      const enabled = (entries || []).filter(en => en && en.enabled !== false);
      const fmtLike = enabled.some(en => typeof en.content === 'string' && (en.content.indexOf('<libido_status>') >= 0 || en.content.indexOf('<role_name="') >= 0 || en.content.indexOf('<status_profile') >= 0));
      if (fmtLike) { log('info', '世界书 [格式定义类，自动跳过] ' + n); continue; }
      let got = 0;
      enabled.forEach(function (en) {
        const e = normalizeEntry(en, n);
        if (!e.content.trim()) return;
        let active = false;
        if (e.constant) active = true;
        else if (e.selective) {
          active = e.keys.length > 0 && e.keys.some(k => k && chatText.indexOf(k.toLowerCase()) >= 0);
        }
        // 向量化及其它：不激活（与酒馆默认一致）
        if (active) { all.push(e); got++; }
      });
      log('info', '世界书 [兜底扫描·按酒馆规则] ' + n + '：激活 ' + got + ' 条');
    } catch (e) {
      log('warn', '读取世界书内容失败: ' + n + ' → ' + String(e && e.message || e));
    }
  }
  if (!all.length) return { str: '', n: 0 };
  const byST = sortEntriesByST(all);
  const str = joinSorted(byST);
  const n = byST.before.length + byST.after.length + byST.depth.length;
  log('info', '世界书 [兜底] 参与 ' + n + ' 条（before ' + byST.before.length + ' / after ' + byST.after.length + ' / 深度 ' + byST.depth.length + '）');
  return { str: str, n: n };
}

/** 收集要发给状态栏生成的世界书资料（书集 = 当前激活书 - 注入书 - 用户不发送；条目激活与排序均按酒馆规则） */
async function collectWorldbookInfo(cfg) {
  // 「不发送所有世界书」开关：完全跳过世界书资料（提示词 = 破甲→最近N楼对话→上一次状态栏→状态栏格式）
  if (cfg.wb_none) {
    log('info', '已开启「不发送所有世界书」，状态栏提示词将跳过世界书资料（含注入书）');
    return '';
  }
  // 主路径：正文生成后（MESSAGE_RECEIVED 触发），事件缓存必有内容 —— 激活完全按酒馆规则
  const fromEvent = collectWorldbookFromEvent(cfg);
  if (fromEvent.n > 0) return fromEvent.str;
  // 兜底（手动测试 / 事件未触发）：模拟酒馆规则扫描
  log('info', '未获取到正文生成时的事件激活缓存，改用兜底扫描（蓝灯常驻 + 绿灯关键词匹配最近对话 + 排序按酒馆规则）');
  const fallback = await scanWorldbookFallback(cfg);
  return fallback.str;
}

/** 应用酒馆正则到单条对话正文（与正文生成一致的 prompt 侧过滤）。
    正文生成时酒馆会对每条消息应用「目标为 prompt」的正则（如屏蔽思维链/行动选项的全局正则）；
    状态栏助手用 generateRaw 显式拼提示词完全绕开预设，若不手动应用正则，
    这些原始标签会原样泄漏进状态栏提示词。这里用 formatAsTavernRegexedString
    复刻酒馆的正则处理：按消息角色选 source（玩家=user_input / AI=ai_output）、
    目标传 'prompt'、depth 传该楼深度（最新楼=0），失败时回退原文不影响现有功能。 */
function regexedChatBody(body, role, depth) {
  try {
    const fmt = thFn('formatAsTavernRegexedString');
    if (!fmt) return body;
    const source = role === 'user' ? 'user_input' : (role === 'assistant' ? 'ai_output' : '');
    if (!source) return body;
    const opt = (depth != null && depth >= 0) ? { depth: depth } : {};
    return String(fmt(body, source, 'prompt', opt) || '');
  } catch (e) {
    log('warn', '对话正文应用正则失败，回退原文: ' + String(e && e.message || e));
    return body;
  }
}

/** 最近 n 楼可见对话（玩家 + AI 正文；排除隐藏的状态栏楼层；完整内容不截断）。
    所有模式下都会剔除正文里内嵌的 <libido_status> 状态栏块（同楼显示方案），
    并应用酒馆正则（prompt 侧，与正文生成一致：剥掉思维链/行动选项等标签），
    对话只保留纯正文；状态栏数据只通过「上一次状态栏数据」段发送（增量更新依据），不混入对话。 */
function getRecentChat(n) {
  try {
    const last = thFn('getLastMessageId')();
    if (last < 0) return [];
    const from = Math.max(0, last - 8 + 1);
    let msgs = [];
    try {
      // 不传 hide_state（默认取全部），避免过滤逻辑误伤 AI 正文；
      // 只在本侧剔除我们自己建的隐藏状态栏楼层（is_hidden === true）
      msgs = thFn('getChatMessages')(from + '-' + last) || [];
    } catch (e) {}
    let logSample = true; // 每次生成只打印一条正则处理对比，便于验证屏蔽正则是否生效
    return msgs
      .filter(m => !(m && m.is_hidden === true))
      .slice(-n)
      .map(m => {
        const who = m.role === 'user' ? '玩家' : (m.role === 'assistant' ? (m.name || '角色') : '系统');
        // 剔除该楼正文里内嵌的状态栏块（连同前后多余空行），只保留纯正文
        const body = String(m.message || '').replace(/[\s]*<libido_status>[\s\S]*?<\/libido_status>[\s]*/gi, '').trim();
        // 应用酒馆正则（与正文生成一致的 prompt 侧过滤：剥掉思维链/行动选项等），失败回退原文
        const filtered = regexedChatBody(body, m.role, last - m.message_id).trim();
        if (logSample && m.role === 'assistant' && filtered !== body) {
          logSample = false;
          const hasTag = /<think|<thinking|<content|<suggestions/i.test(body);
          log('info', '最近对话已应用酒馆正则（示例·最新AI正文）：' + body.length + ' 字符 → ' + filtered.length + ' 字符' + (hasTag ? '（原文含思维链/行动选项标签，已按屏蔽正则剔除）' : ''));
        }
        // 完整内容：不截断、不压缩换行，保证预览与发送给 AI 的一致
        return who + ': ' + filtered;
      })
      .filter(s => s && s.length > 3);
  } catch (e) {
    log('warn', '读取最近对话失败: ' + String(e && e.message || e));
    return [];
  }
}

/* ==================== 生成管线 ==================== */

let running = false; // 防重入锁

/** 剔除文本中的图片语法（防止图片被带进发送给 AI 的提示词导致部分接口 Bad Request）：
    - markdown 图片 ![alt](url) → 保留 alt 文本
    - <img ...> 标签 → 删除
    - base64 内联图片 data:image/... → 替换为 [图片]
    - 大段 base64 数据（非图片的 data:...）→ 截断为占位 */
function stripImages(t) {
  return String(t == null ? '' : t)
    .replace(/!\[([^\]]*)\]\([^)]*\)/g, function (m, alt) { return (alt || '').trim() ? alt : '[图片]'; })
    .replace(/<img[^>]*>/gi, '')
    .replace(/data:image\/[a-z0-9.+-]+;base64,[A-Za-z0-9+/=]+/gi, '[图片]')
    .replace(/data:[a-z0-9.+-]+\/[a-z0-9.+-]+;base64,[A-Za-z0-9+/=]{200,}/gi, '[数据]');
}

/** 提示词段定义（顺序可在面板「提示词顺序」调整）：
    key: 面板排序 key；label: 栏目名；mk: 生成该段内容（空串=跳过该段） */
const SBH_PROMPT_ORDER_DEFAULT = ['jailbreak', 'format', 'rules', 'gen_rules', 'worldbook', 'last', 'chat'];

function buildPromptSegments(cfg, wbText, recent, lastStatus) {
  return {
    jailbreak: { label: '破甲提示词', mk: function () { return cfg.jailbreak && cfg.jailbreak.trim() ? cfg.jailbreak : ''; } },
    format: { label: '状态栏格式', mk: function () { return cfg.format_text && cfg.format_text.trim() ? cfg.format_text : ''; } },
    rules: { label: '推演规则', mk: function () { return cfg.rules_text && cfg.rules_text.trim() ? cfg.rules_text : ''; } },
    gen_rules: { label: '状态栏规则', mk: function () { return cfg.gen_rules_text && cfg.gen_rules_text.trim() ? cfg.gen_rules_text : ''; } },
    last: { label: '上一次状态栏', mk: function () { return lastStatus ? '【上一次状态栏（本次必须在其基础上增量更新：好感度/性欲等数值写 旧值→新值 (原因)；[生理健康监测] 按推演规则推进）】\n' + lastStatus : ''; } },
    worldbook: { label: '世界书资料', mk: function () { return wbText ? '【当前世界书资料（角色设定/世界设定）】\n' + wbText : ''; } },
    chat: { label: '最近对话', mk: function () { return recent.length ? '【最近对话】\n' + recent.join('\n') : ''; } },
  };
}

/** 组装状态栏生成提示词（完全自定义，绕开酒馆预设 = 上下文隔离）。
    段顺序由 cfg.prompt_order 决定（默认 破甲→状态栏格式→推演规则→状态栏规则→上一次状态栏→
    世界书→最近对话，可在面板「提示词顺序」调整）。
    暗骰 {{roll 1d100}} 原样保留在提示词中，由 AI 自主掷骰判定（插件不干预）。
    所有段统一剔除图片语法，避免「正文含图片」时接口返回 Bad Request。 */
function buildPrompts(cfg, wbText, recent, lastStatus) {
  const segs = buildPromptSegments(cfg, wbText, recent, lastStatus);
  const order = Array.isArray(cfg.prompt_order) && cfg.prompt_order.length ? cfg.prompt_order : SBH_PROMPT_ORDER_DEFAULT.slice();
  const ps = [];
  order.forEach(function (key) {
    const s = segs[key];
    if (!s) return;
    const content = String(s.mk() || '');
    if (!content.trim()) return;
    ps.push({ role: 'system', content: stripImages(content) });
  });
  ps.push({ role: 'user', content: '请根据以上资料输出本次状态栏。只输出 <libido_status> 块本身（含 <role_name> 与 [生理健康监测]），不要输出任何其他内容。' });
  return ps;
}

/** 从 AI 结果提取 <libido_status> 状态栏块（健壮版：抗干扰/大小写/多块/残缺标签）。
    策略：
    1) 收集所有 <libido_status>...</libido_status> 候选（大小写不敏感）；
    2) 按"结构完整度"评分（含 role_name/后宫名单/场景概况/生理健康监测等结构越多分越高），
       取最高分；同分取更靠后的候选——模型通常把状态栏输出在最后，块前的
       思考文本/杂音、以及思考文本里引用模板造成的假容器标签都会被正确跳过；
    3) 无完整块但内容含状态栏结构 → 截断块前杂音 + 去掉残余容器标签后智能包裹；
    4) 否则返回空（触发失败重试，不把乱码当状态栏）。 */
function extractStatus(text) {
  if (!text) return '';
  const t = String(text);
  // 1+2) 收集候选并按结构完整度评分
  const re = /<libido_status>([\s\S]*?)<\/libido_status>/gi;
  let best = null, bestScore = 0, bestIdx = -1;
  let m;
  while ((m = re.exec(t))) {
    const inner = m[1] || '';
    let score = 0;
    if (/<role_name="[^"]+">/i.test(inner)) score += 3;
    if (/\[后宫名单\]/i.test(inner)) score += 2;
    if (/\[场景概况\]|\[当前任务\]/.test(inner)) score += 2;
    if (/\[生理健康监测\]/.test(inner)) score += 2;
    if (/\[心理与记忆\]|\[身份与异常\]/.test(inner)) score += 1;
    if (score > bestScore || (score > 0 && score === bestScore && m.index > bestIdx)) {
      bestScore = score;
      best = m[0];
      bestIdx = m.index;
    }
  }
  if (best && bestScore > 0) return best.trim();
  // 3) 无完整块：内容含状态栏结构 → 截断块前杂音、去掉残余容器标签后智能包裹
  const inner = t.trim();
  if (/<role_name="[^"]+">/i.test(inner) || /\[场景概况\]/.test(inner) || /\[当前任务\]/.test(inner) || /\[后宫名单\]/.test(inner) || /\[生理健康监测\]/.test(inner)) {
    const start = inner.search(/<role_name="[^"]+">|\[场景概况\]|\[当前任务\]|\[后宫名单\]|\[生理健康监测\]/i);
    const cleaned = (start > 0 ? inner.slice(start) : inner)
      .replace(/<libido_status>/gi, '')   // 去掉残余开标签，避免包裹后重复
      .replace(/<\/libido_status>/gi, '') // 去掉残余闭标签
      .trim();
    if (cleaned) return '<libido_status>\n' + cleaned + '\n</libido_status>';
  }
  return '';
}

/** 将状态栏追加到「触发它生成的那一栋正文楼层」下方（同一楼显示，不是新楼层）。
    targetId：触发时记录的目标楼层号（MESSAGE_RECEIVED 的 message_id / 手动测试为当时最新楼）。
    这样即使生成期间用户又发了下一楼正文，状态栏也只会插入到正确的目标楼，不会插错楼层。
    做法：取目标楼正文 → 剥离旧 <libido_status> 块 → 追加新状态栏 →
    更新该楼层（refresh:'affected' 触发 markdown 渲染与多角色状态栏正则）。 */
async function upsertStatusMessage(clean, targetId) {
  let tid = (targetId != null && targetId >= 0) ? targetId : null;
  try { if (tid == null) tid = thFn('getLastMessageId')(); } catch (e) {}
  if (tid == null || tid < 0) {
    log('warn', '没有可用的正文楼层，状态栏未显示');
    return;
  }
  try {
    let cur = '';
    let exists = false;
    try {
      const arr = thFn('getChatMessages')(tid) || [];
      if (arr.length) { cur = String(arr[0].message || ''); exists = true; }
    } catch (e) {
      log('warn', '读取目标楼层 #' + tid + ' 失败: ' + String(e && e.message || e));
    }
    // 目标楼层在生成期间不存在（被删除等）→ 回退到最新楼，避免状态栏丢失
    if (!exists) {
      log('warn', '目标楼层 #' + tid + ' 不存在，回退到最新楼层');
      try { tid = thFn('getLastMessageId')(); } catch (e2) {}
      try {
        const arr2 = thFn('getChatMessages')(tid) || [];
        if (arr2.length) cur = String(arr2[0].message || '');
      } catch (e3) {}
    }
    // 剥离正文中旧的 <libido_status> 块（连同前后多余空行），避免同楼重复堆积
    const stripped = cur.replace(/[\s]*<libido_status>[\s\S]*?<\/libido_status>[\s]*/gi, '');
    const newMsg = (stripped ? stripped.trimEnd() + '\n\n' : '') + clean;
    await thFn('setChatMessages')([{ message_id: tid, message: newMsg }], { refresh: 'affected' });
    log('info', '已将状态栏追加到目标正文楼层 #' + tid + ' 下方（同一楼显示）');
  } catch (e) {
    log('error', '状态栏追加到正文楼层失败: ' + String(e && e.stack || e));
    try { toastr.error('状态栏追加到正文楼层失败，详情见日志'); } catch (e2) {}
  }
}

/** 楼层内提示（如：未配置独立 API 时） */
async function insertNoticeFloor(msg) {
  try {
    let name = '状态栏';
    try { name = thFn('getCurrentCharacterName')() || '状态栏'; } catch (e) {}
    await thFn('createChatMessages')([{ role: 'assistant', name: name, message: '【状态栏助手】' + msg, is_hidden: true }], { refresh: 'affected' });
  } catch (e) {
    log('warn', '插入提示楼层失败: ' + String(e && e.message || e));
  }
}

/** 清理旧楼内嵌的状态栏块：除目标楼（最新状态栏所在楼）外，把最近 30 楼里
    其它正文中内嵌的 <libido_status> 块剥掉（只留纯正文）。
    这样正文生成时聊天历史里只有 1 个最新状态栏，不会每楼都带一个旧状态栏。 */
async function cleanupOldStatusFloors(keepFloor) {
  try {
    const last = thFn('getLastMessageId')();
    if (last == null || last < 0) return;
    const from = Math.max(0, last - 29); // 最近 30 楼
    let msgs = [];
    try { msgs = thFn('getChatMessages')(from + '-' + last) || []; } catch (e) {}
    const updates = [];
    msgs.forEach(function (m) {
      if (!m || m.message_id === keepFloor) return;
      const body = String(m.message || '');
      const cleaned = body.replace(/[\s]*<libido_status>[\s\S]*?<\/libido_status>[\s]*/gi, '').trim();
      if (cleaned !== body.trim() && cleaned) {
        updates.push({ message_id: m.message_id, message: cleaned });
      }
    });
    if (updates.length) {
      await thFn('setChatMessages')(updates, { refresh: 'affected' });
      log('info', '已清理 ' + updates.length + ' 栋旧楼的内嵌状态栏（只保留最新状态栏所在楼 #' + keepFloor + '）');
    } else {
      log('info', '无需清理：旧楼无内嵌状态栏（仅目标楼 #' + keepFloor + ' 含状态栏）');
    }
  } catch (e) {
    log('warn', '清理旧楼状态栏失败: ' + String(e && e.message || e));
  }
}

/** 当前生成请求 id（功能 C：供面板「中止本次生成」精确停止） */
let currentGenId = null;

/** 主流程：生成状态栏（功能 C 开启时失败自动重试） */
async function runStatusBar(reason, targetId, noOld, retriesLeft) {
  if (running) {
    log('warn', '已有状态栏生成任务进行中，本次触发忽略 (' + reason + ')');
    try { toastr.warning('状态栏生成中，请稍候…'); } catch (e) {}
    return;
  }
  running = true;
  const t0 = Date.now();
  // 目标楼层：触发时记录（自动触发为 MESSAGE_RECEIVED 的 message_id；手动测试为当时最新楼）。
  // 生成期间用户可能已发下一楼正文，生成完必须插回 target，而不是插到最新楼。
  let target = (targetId != null && targetId >= 0) ? targetId : null;
  try { if (target == null) target = thFn('getLastMessageId')(); } catch (e) {}
  const genId = 'statusbar-' + Date.now() + '-' + Math.floor(Math.random() * 10000);
  currentGenId = genId; // 供「中止本次生成」停止
  // 首次调用时根据功能 C 开关决定剩余重试次数
  let retries = retriesLeft;
  if (retries === undefined) {
    try {
      const s = loadSettings();
      retries = (s.features && s.features.retry) ? (Number(s.retry_count) || 2) : 0;
    } catch (e) { retries = 0; }
  }
  try {
    log('info', '[' + reason + '] 开始生成状态栏 (generation_id=' + genId + '，目标正文楼层 #' + target + ')');
    setRunStatus('正在生成…', '#b7791f');

    /* 0. 每次发送状态栏提示词之前刷新设置与面板（保证最新配置/最新世界书/最新上一次状态栏生效）；
           功能 F 开启时载入角色记忆配置（角色变量优先） */
    cfg = loadSettings();   // 使用模块级 cfg（let），保证 finally 里可重新赋值刷新
    if (cfg.features && cfg.features.share_cfg) {
      try { cfg = loadCharCfg(loadSettings()); } catch (e2) {}
    }
    renderWb();
    refreshPreviews();

    /* 1. 校验 API 模式与生成参数 */
    let prof = null;
    if (cfg.api_mode === 'custom') {
      prof = (cfg.profiles || []).find(p => p && p.enabled);
      if (!prof || !prof.apiurl) {
        const err = '独立API模式未启用任何有效配置（apiurl 为空）。请先在设置面板配置独立 API。';
        log('error', err);
        try { toastr.error(err); } catch (e2) {}
        await insertNoticeFloor('状态栏未生成：' + err);
        return;
      }
    }
    const customApi = buildCustomApi(cfg, prof);
    if (cfg.api_mode === 'custom') {
      log('info', '使用独立API配置: ' + (prof.name || '未命名') + ' (apiurl=' + prof.apiurl + ', model=' + (prof.model || '未指定') + ', source=' + (prof.source || 'openai') + ')');
    } else {
      log('info', customApi ? '使用酒馆当前 API（连接跟随当前源/模型），覆盖参数：' + JSON.stringify(customApi) : '使用酒馆当前 API（连接与参数均跟随酒馆当前源/模型，不覆盖）');
    }

    /* 2. 收集世界书资料 */
    log('info', '正在收集世界书资料…');
    const wbText = await collectWorldbookInfo(cfg);
    log('info', '世界书资料收集完成，共 ' + wbText.length + ' 字符');

    /* 3. 最近对话（楼层数可调，默认 4）
       getRecentChat 已在所有模式下剔除正文内嵌的状态栏块，对话只含纯正文 */
    const chatDepth = Math.max(1, Math.min(20, Number(cfg.chat_depth) || 4));
    const recent = getRecentChat(chatDepth);
    if (noOld) log('info', '重新生成模式：对话已剔除状态栏块，且不发送上一次状态栏');
    log('info', '读取最近对话 ' + recent.length + ' 楼（设置 ' + chatDepth + ' 楼，均不含状态栏数据）');

    /* 4. 上一次状态栏（聊天级隔离：换角色/换聊天各自独立；状态栏数据只在这里发送；
           重新生成 noOld 时不发送，完全基于正文+世界书重新生成；
           重生成正文（自动触发(regenerate)）时改为发送「当前楼状态栏之前的一份」，
           而不是当前楼那条状态栏） */
    const lastStatus = (noOld ? '' : resolveLastStatus(reason, target));
    log('info', noOld ? '重新生成模式：不发送上一次状态栏（完全重新生成）' : (lastStatus ? ('已读取上一次状态栏 ' + lastStatus.length + ' 字符（当前聊天，将作为【第 5 段·上一次状态栏数据】发送）') : '无上一次状态栏数据（当前聊天首次生成，跳过该段）'));

    /* 5. 组装提示词 + 字数限制 */
    const prompts = buildPrompts(cfg, wbText, recent, lastStatus);
    const totalChars = prompts.reduce(function (s, p) { return s + (p && p.content ? p.content.length : 0); }, 0);
    const limit = Number(cfg.max_send_chars) || 50000;
    // 「不限制最大发送字数」勾选（默认）时跳过超限检查；仅显式取消勾选（=== false 不成立）才启用限制
    if (cfg.no_limit_send_chars === false && totalChars > limit) {
      const msg = '状态栏提示词总长度 ' + totalChars + ' 字符，超过最大发送字数 ' + limit + '，已停止生成。可在「生成参数（高级）」调大限制，或减少世界书/对话。';
      log('error', msg);
      try { toastr.error(msg); } catch (e2) {}
      setRunStatus('已停止：超过最大发送字数', '#c0392b');
      return;
    }
    log('info', '提示词组装完成，共 ' + prompts.length + ' 段，总长度 ' + totalChars + ' 字符（' + (cfg.no_limit_send_chars === false ? '限制 ' + limit : '不限制发送字数') + '，已剔除图片语法）');

    /* 5.5 保存本次实际发送的提示词（供「查看日志」查看最近一次发送内容） */
    try {
      cfg.last_prompt = prompts.map(function (p) { return { role: p.role, content: String(p.content || '') }; });
      saveSettings(cfg);
      log('info', '已保存本次发送的提示词（' + prompts.length + ' 段，可在「查看日志」顶部查看）');
    } catch (e) {
      log('warn', '保存发送提示词失败: ' + String(e && e.message || e));
    }

    /* 6. 请求 AI 生成 */
    try { toastr.info('正在生成状态栏…'); } catch (e2) {}
    log('info', '正在请求 AI 生成状态栏…');
    const result = await thFn('generateRaw')({
      generation_id: genId,
      should_silence: true,          // 静默生成：不改变发送按钮状态
      ordered_prompts: prompts,      // 完全自定义提示词，不使用酒馆预设
      custom_api: customApi || undefined,
    });
    const text = (typeof result === 'string') ? result : (result && result.content) ? result.content : '';
    if (!text) throw new Error('AI 返回为空');
    log('info', 'AI 返回原文长度 ' + text.length + ' 字符');

    /* 7. 清洗：提取 <libido_status> 块 */
    const clean = extractStatus(text);
    if (!clean) {
      log('warn', '生成结果中未找到 <libido_status> 块，原文开头: ' + text.slice(0, 160));
      throw new Error('生成结果中未找到 <libido_status> 状态栏内容，请检查提示词或模型');
    }

    /* 8. 插入/更新状态栏到目标正文楼层 */
    await upsertStatusMessage(clean, target);

    /* 9. 保存本次状态 + 运行记录（上一次状态栏按聊天隔离存储；最近 5 次历史同样入聊天变量） */
    setLastStatus(clean);                       // 写入当前聊天的「上一次状态栏」
    pushStatusHistory(clean, target, reason);   // 追加进「最近 5 次」历史（保留最近 5 次）
    cfg.last_status_floor = target;             // 记录状态栏所在正文楼层，供「重新生成状态栏」定位
    cfg.last_run = { time: fmtTime(), ok: true, ms: Date.now() - t0, reason: reason };
    saveSettings(cfg);

    /* 10. 清理旧楼内嵌状态栏：只保留最新状态栏所在楼，正文生成时只发 1 个最新状态栏 */
    await cleanupOldStatusFloors(target);

    /* 11. 功能钩子（全部默认关闭，按 features 开关执行） */
    const feat = cfg.features || {};
    if (feat.sync_vars) syncStatVars(clean);            // A 数值同步到聊天变量
    if (feat.history) pushHistory(clean, target, reason); // B 历史快照
    if (feat.manual_edit && reason !== '自动触发(normal)' && reason !== '自动触发(regenerate)') {
      // D 手动触发视为主动覆盖：清除手改锁定
      try { cfg.manual_lock_remaining = 0; saveSettings(cfg); } catch (e2) {}
    }

    const used = ((Date.now() - t0) / 1000).toFixed(1);
    log('success', '状态栏生成成功！用时 ' + used + ' 秒');
    try { toastr.success('状态栏生成成功，用时 ' + used + ' 秒'); } catch (e2) {}
  } catch (e) {
    // 功能 C：失败自动重试（先释放锁，再递归重跑；中止/字数超限等不重试）
    if (retries > 0 && !(e && e.message && String(e.message).indexOf('已停止：超过最大发送字数') >= 0)) {
      log('warn', '状态栏生成失败，自动重试（剩余 ' + retries + ' 次）: ' + String(e && e.message || e));
      try { toastr.warning('状态栏生成失败，正在自动重试…'); } catch (e2) {}
      running = false;
      currentGenId = null;
      return runStatusBar(reason, targetId, noOld, retries - 1);
    }
    const errMsg = (e && e.stack) ? e.stack : String(e);
    log('error', '状态栏生成失败: ' + errMsg);
    try { toastr.error('状态栏生成失败，详情见「查看日志」'); } catch (e2) {}
    try {
      const c2 = loadSettings();
      c2.last_run = { time: fmtTime(), ok: false, ms: Date.now() - t0, reason: reason, err: String(e && e.message || e) };
      saveSettings(c2);
    } catch (e2) {}
  } finally {
    running = false;
    if (currentGenId === genId) currentGenId = null;
    // 同步面板数据与显示（状态栏生成后自动刷新）
    try {
      cfg = loadSettings();
      renderWb();
      renderLast();
      refreshPreviews();
      const lr = cfg.last_run;
      if (lr) setRunStatus((lr.ok ? '上次生成成功' : '上次生成失败') + '，用时 ' + (lr.ms / 1000).toFixed(1) + ' 秒' + (lr.err ? '：' + lr.err : ''), lr.ok ? '#1f9d55' : '#c0392b');
    } catch (e3) {}
  }
}

/** 重新生成状态栏：针对「上一次状态栏所在正文楼层」重新跑一遍生成（重roll），
    无记录时回退到最新楼层。生成完会替换该楼旧的 <libido_status> 块。 */
function rerunStatusBar() {
  const s = loadSettings();
  let floor = null;
  try {
    floor = (s.last_status_floor != null && s.last_status_floor >= 0) ? s.last_status_floor : null;
  } catch (e) {}
  log('info', floor != null ? '「重新生成状态栏」：目标楼层 #' + floor + '（完全不发送旧状态栏，重新生成）' : '「重新生成状态栏」：无上一次状态栏楼层记录，回退到最新楼（重新生成）');
  runStatusBar('重新生成', floor, true); // noOld=true：旧状态栏不出现在提示词中
}

/** 手动生成状态栏（输入框上方快捷按钮）：发送上一次状态栏（noOld=false），
    状态栏追加到最新正文楼层下方。不受「启用自动生成状态栏」开关影响
    （runStatusBar 本身不检查 enabled，仅自动触发会检查）。 */
function manualStatusBar() {
  log('info', '「手动生成状态栏」：发送上一次状态栏，目标楼层 = 最新正文楼');
  try { toastr.info('状态栏助手：正在手动生成状态栏…'); } catch (e) {}
  runStatusBar('手动生成', null, false);
}

/** 修正标签间距：将最新正文楼层中紧贴的 XML 闭合/开放标签之间补回空行
    （如 </content><suggestions> → </content>\n\n<suggestions>），
    让酒馆 marked 把各标签块当作独立 HTML 块，渲染正则锚点稳定命中、
    textarea 内容不被"吃掉"，从而修复「状态栏空框但文字在原文里」的问题。 */
async function fixStatusBar() {
  try {
    const last = thFn('getLastMessageId')();
    if (last == null || last < 0) { try { toastr.warning('当前没有消息楼层'); } catch (e) {} return; }
    const arr = thFn('getChatMessages')(last) || [];
    if (!arr.length) { try { toastr.warning('无法读取最新楼层'); } catch (e) {} return; }
    const msg = arr[0];
    const body = String(msg.message || '');
    // 匹配 </tagname>（后最多跟一个换行）紧接 <tagname>，替换为两个换行隔开
    const fixed = body.replace(/(<\/\w+>)(\n{0,1})(<\w+)/g, '$1\n\n$3');
    if (fixed === body) {
      log('info', '「修正标签间距」：正文中 XML 标签间已有足够空行，无需修正');
      try { toastr.info('标签间已有空行，无需修正'); } catch (e) {}
      return;
    }
    await thFn('setChatMessages')([{ message_id: msg.message_id, message: fixed }], { refresh: 'affected' });
    const cnt = Math.max(0, (fixed.match(/(<\/\w+>)\n\n(<\w+)/g) || []).length - (body.match(/(<\/\w+>)\n\n(<\w+)/g) || []).length);
    log('success', '「修正标签间距」：已为 ' + cnt + ' 处相邻 XML 标签补回空行');
    try { toastr.success('已修正 ' + cnt + ' 处标签间距'); } catch (e) {}
  } catch (e) {
    log('error', '修正标签间距失败: ' + String(e && e.stack || e));
    try { toastr.error('修正失败，详情见日志'); } catch (e2) {}
  }
}

/** 组装 custom_api：独立配置模式带 apiurl/key/model/source；任何模式都可覆盖 max_tokens/temperature
    （tavern 模式仅传参数时使用当前 ST 源，覆盖对应参数；不设参数时返回 undefined = 完全跟随酒馆） */
function buildCustomApi(cfg, prof) {
  const p = cfg.gen_params || {};
  const api = {};
  if (cfg.api_mode === 'custom' && prof) {
    api.apiurl = prof.apiurl;
    api.key = prof.key || '';
    api.model = prof.model || '';
    api.source = prof.source || 'openai';
  }
  const mt = Number(p.max_tokens);
  // 「不限制最大 token」勾选（默认）时不覆盖 max_tokens；仅显式取消勾选才按填写值覆盖
  if (p.no_limit_tokens === false && mt && mt > 0) api.max_tokens = mt;
  const tmp = p.temperature;
  if (tmp !== '' && tmp !== null && tmp !== undefined && !isNaN(Number(tmp))) api.temperature = Number(tmp);
  return Object.keys(api).length ? api : undefined;
}

/** 测试连接 / 获取模型：优先走酒馆助手 getModelList（经酒馆后端转发，不受浏览器 CORS 限制，
    可正常访问 opencode.ai 等「OPTIONS 预检放行但 GET 响应缺 CORS 头」的接口）；
    旧版酒馆助手无该接口时回退为浏览器直接 fetch /models（可能被 CORS 拦截，仅作兜底）。 */
async function testConnection(apiurl, key) {
  const url = String(apiurl || '').trim();
  if (!url) return { ok: false, msg: 'apiurl 为空，请填写 API 地址' };
  const getModels = thFn('getModelList');
  if (getModels) {
    try {
      const res = await getModels({ apiurl: url, key: key || '' });
      const models = (Array.isArray(res) ? res : []).map(m => String(m)).filter(Boolean);
      return { ok: true, msg: '连接成功！可用模型 ' + models.length + ' 个' + (models.length ? '：' + models.slice(0, 5).join(', ') + (models.length > 5 ? '…' : '') : ''), models: models };
    } catch (e) {
      return { ok: false, msg: '连接失败: ' + String(e && e.message || e) };
    }
  }
  // 兜底：旧版酒馆助手无 getModelList 接口，浏览器直连（可能被目标站 CORS 拦截）
  try {
    const base = url.replace(/\/+$/, '');
    const res = await fetch(base + '/models', {
      method: 'GET',
      headers: {
        'Content-Type': 'application/json',
        ...(key ? { Authorization: 'Bearer ' + key } : {}),
      },
    });
    if (!res.ok) {
      const t = await res.text();
      throw new Error('HTTP ' + res.status + ' ' + res.statusText + ' ' + t);
    }
    const data = await res.json();
    const models = ((data && data.data) || []).map(m => m && m.id).filter(Boolean);
    return { ok: true, msg: '连接成功！可用模型 ' + models.length + ' 个' + (models.length ? '：' + models.slice(0, 5).join(', ') + (models.length > 5 ? '…' : '') : ''), models: models };
  } catch (e) {
    return { ok: false, msg: '连接失败: ' + String(e && e.message || e) + '（当前酒馆助手版本过旧，浏览器直连可能被 CORS 拦截；实际生成走酒馆后端不受影响，可忽略此报错直接使用）' };
  }
}

/* ==================== 设置面板（挂到酒馆扩展设置区 #extensions_settings2） ==================== */

let cfg = null; // 面板当前编辑中的配置（loadSettings 深拷贝）

const SBH_SEC_STYLE = 'margin:10px 0 4px;font-weight:700;border-bottom:1px dashed var(--SmartThemeBorderColor);padding-bottom:2px;color:var(--SmartThemeQuoteColor)';

/** 预览框：只读 textarea，可像破甲提示词那样拖拽调整大小 */
function fixedBox() {
  return $('<textarea class="text_pole" readonly style="width:100%;box-sizing:border-box;height:120px;min-height:60px;resize:vertical;margin-bottom:4px">');
}

/** 可伸缩栏目：<details> 区块（默认展开 open）；extra 追加到 summary 右侧 */
function sbhSection(title, open, extra) {
  const $s = $('<details class="sbh-sec"' + (open ? ' open' : '') + '>');
  const $sum = $('<summary>');
  $sum.append($('<span style="flex:0 0 auto">').text(title));
  if (extra) $sum.append(extra);
  $s.append($sum);
  return $s;
}

/** 构建设置面板：inline-drawer 常驻扩展程序区域（参照官方扩写脚本） */
function initPanel() {
  cfg = loadSettings();

  // 防重复挂载
  try { $('#sbh-drawer').remove(); } catch (e) {}

  const $panel = $('<div id="sbh-drawer" class="inline-drawer">').attr('script_id', SBH_SID || '');
  // 挂载兜底：优先扩展设置区 #extensions_settings2，找不到依次回退 #extensions_settings /
  // #extensions_list / body，保证设置面板一定可见（jQuery appendTo 找不到目标会静默失败）
  const mountTargets = ['#extensions_settings2', '#extensions_settings', '#extensions_list', 'body'];
  let mountedAt = '';
  for (let mi = 0; mi < mountTargets.length; mi++) {
    try {
      const $t = $(mountTargets[mi]);
      if ($t.length) {
        $panel.appendTo($t);
        mountedAt = mountTargets[mi];
        break;
      }
    } catch (e2) {}
  }
  if (!mountedAt) {
    log('error', '设置面板挂载失败：未找到任何可挂载容器（#extensions_settings2 / #extensions_settings / #extensions_list / body）');
    try { toastr.error('状态栏助手设置面板挂载失败，请查看日志'); } catch (e3) {}
    return;
  }
  log('info', '设置面板已挂载到 ' + mountedAt + (mountedAt === 'body' ? '（未找到扩展设置区，已挂到页面末尾，可直接滚动查看）' : ''));

  // 局部样式（挂在面板内，作用域限定 #sbh-drawer）
  $panel.append($('<style>').text(
    '#sbh-drawer .sbh-x{cursor:pointer;color:#c0392b;font-weight:700;font-size:15px;padding:0 6px;border-radius:3px;user-select:none;flex:0 0 auto}#sbh-drawer .sbh-x:hover{background:rgba(192,57,43,.15)}'
    + '#sbh-drawer .sbh-link{cursor:pointer;color:var(--SmartThemeQuoteColor);font-size:12px;text-decoration:underline;font-weight:600}#sbh-drawer .sbh-link:hover{opacity:.8}'
    + '#sbh-drawer details.sbh-sec{border:1px solid var(--SmartThemeBorderColor);border-radius:10px;background:var(--SmartThemeBlurTintColor);margin:8px 0;overflow:hidden}'
    + '#sbh-drawer details.sbh-sec > summary{list-style:none;cursor:pointer;padding:8px 12px;font-weight:700;color:var(--SmartThemeQuoteColor);display:flex;align-items:center;gap:8px;user-select:none;-webkit-user-select:none;border-bottom:1px solid transparent}'
    + '#sbh-drawer details.sbh-sec > summary::-webkit-details-marker{display:none}'
    + '#sbh-drawer details.sbh-sec > summary::before{content:"▸";font-size:13px;transition:transform .15s;flex:0 0 auto}'
    + '#sbh-drawer details.sbh-sec[open] > summary::before{transform:rotate(90deg)}'
    + '#sbh-drawer details.sbh-sec[open] > summary{border-bottom:1px dashed var(--SmartThemeBorderColor)}'
    + '#sbh-drawer details.sbh-sec .sbh-sec-body{padding:8px 12px 10px}'
