  $panel.on('click', '[data-sbh="export"]', function () {
    const text = JSON.stringify(cfg.profiles, null, 2);
    try {
      const blob = new Blob([text], { type: 'application/json;charset=utf-8' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = '状态栏助手-独立API配置.json';
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      setTimeout(function () { try { URL.revokeObjectURL(url); } catch (e2) {} }, 2000);
      toastr.success('已导出配置文件（' + cfg.profiles.length + ' 套），请检查下载');
      log('info', '已导出配置文件（' + cfg.profiles.length + ' 套）');
