  /** 从面板读取全部设置并保存（手动保存与自动保存共用） */
  function collectAndSave() {
    const $p = $panel;
    cfg.enabled = !!$p.find('[data-sbh="enabled"]').is(':checked');
    const mode = $p.find('[data-sbh="mode"]:checked').val();
    cfg.api_mode = mode === 'custom' ? 'custom' : 'tavern';
    cfg.format_text = String($p.find('[data-sbh="format"]').val() || '');
    cfg.jailbreak = String($p.find('[data-sbh="jailbreak"]').val() || '');
    cfg.rules_text = String($p.find('[data-sbh="rules"]').val() || '');
    cfg.gen_rules_text = String($p.find('[data-sbh="gen-rules"]').val() || '');

    // 增强功能开关（默认全关，面板勾选即开启）
    if (!cfg.features) cfg.features = {};
    ['sync_vars', 'history', 'retry', 'manual_edit', 'group_chat', 'share_cfg'].forEach(function (k) {
      cfg.features[k] = !!$p.find('[data-sbh="feat-' + k + '"]').is(':checked');
    });
    const rc = Number($p.find('[data-sbh="retry-count"]').val());
    cfg.retry_count = rc >= 0 ? rc : 2;
    const ml = Number($p.find('[data-sbh="manual-locks"]').val());
    cfg.manual_edit_locks = ml >= 0 ? ml : 3;

    // 读取各配置行
    const profs = [];
    $p.find('[data-sbh="profiles"] .sbh-prof').each(function () {
      const $row = $(this);
      const i = parseInt($row.data('i'), 10);
      const p = cfg.profiles[i] || {};
      p.name = String($row.find('[data-sbh="p-name"]').val() || '').trim();
      p.apiurl = String($row.find('[data-sbh="p-apiurl"]').val() || '').trim();
      p.key = String($row.find('[data-sbh="p-key"]').val() || '');
      p.model = String($row.find('[data-sbh="p-model"]').val() || '').trim();
      p.source = String($row.find('[data-sbh="p-source"]').val() || '').trim() || 'openai';
      p.enabled = !!$row.find('[data-sbh="p-active"]').is(':checked');
      profs.push(p);
    });
    cfg.profiles = profs;

    // 生成参数（高级）
    cfg.chat_depth = Math.max(1, Math.min(20, Number($p.find('[data-sbh="chat-depth"]').val()) || 4));
    if (!cfg.gen_params) cfg.gen_params = {};
    const mt = Number($p.find('[data-sbh="max-tokens"]').val());
    cfg.gen_params.max_tokens = mt && mt > 0 ? mt : 40000;
    cfg.gen_params.no_limit_tokens = !!$p.find('[data-sbh="no-limit-tokens"]').is(':checked');
    const tp = String($p.find('[data-sbh="temperature"]').val() || '').trim();
    cfg.gen_params.temperature = tp === '' ? '' : Number(tp);
    const msc = Number($p.find('[data-sbh="max-send-chars"]').val());
    cfg.max_send_chars = msc && msc > 0 ? msc : 50000;
    cfg.no_limit_send_chars = !!$p.find('[data-sbh="no-limit-chars"]').is(':checked');

    // 世界书不发送设置
    cfg.wb_none = !!$p.find('[data-sbh="wb-none"]').is(':checked');
    // 世界书排除（勾选状态已实时写入 cfg.excluded_worldbooks，这里只需持久化）
    saveSettings(cfg);
    // 功能 F：开启时同步角色记忆配置（不含 API）
    if (cfg.features && cfg.features.share_cfg) saveCharCfg(cfg);
    return cfg;
  }

