  // D：编辑当前聊天状态栏（面板弹窗编辑 + 手改锁定）
  $panel.on('click', '[data-sbh="feat-edit"]', function () {
    const cur = getLastStatus();
    const $c = $('<div style="display:flex;flex-direction:column;gap:8px;min-width:420px">');
    $c.append($('<div style="font-weight:600">').text('编辑当前聊天状态栏（保存后写回楼层并标记手改锁定）'));
    $c.append($('<textarea class="text_pole" rows="12" style="width:100%;box-sizing:border-box;font-size:12px;font-family:monospace">').val(cur || '（当前暂无状态栏数据）'));
    const $lockSel = $('<select class="text_pole" style="align-self:flex-start">');
    [0, 1, 2, 3, 5, 10].forEach(function (n) { $lockSel.append($('<option value="' + n + '">').text(n === 0 ? '不锁定（下一轮自动更新）' : '锁定 ' + n + ' 轮')); });
    const $lockRow = $('<div class="flex-container" style="gap:6px;align-items:center">').append($('<span style="font-size:12px;opacity:.8">').text('手改锁定')).append($lockSel);
    $c.append($lockRow);
    const $foot2 = $('<div style="display:flex;justify-content:flex-end;gap:8px">')
      .append($('<button class="menu_button" data-sbh-edit="cancel">取消</button>'))
      .append($('<button class="menu_button" data-sbh-edit="ok">保存并锁定</button>'));
    $c.append($foot2);
    try {
      SillyTavern.callGenericPopup($c, SillyTavern.POPUP_TYPE.DISPLAY, undefined, {
        okButton: false, cancelButton: false, wide: true, allowVerticalScrolling: true,
        onOpen: function (popup) {
          $c.find('[data-sbh-edit="cancel"]').on('click', function () { popup.complete(1); });
          $c.find('[data-sbh-edit="ok"]').on('click', async function () {
            try {
              const newText = String($c.find('textarea').val() || '').trim();
              const lock = Number($lockSel.val()) || 0;
              if (!newText) { toastr.error('内容为空，未保存'); return; }
              // 写回楼层（替换旧状态栏块；取最新含状态栏的楼，无则最新楼）
              const last = thFn('getLastMessageId')();
              let target = null;
              if (last != null && last >= 0) {
                const arr = thFn('getChatMessages')(last) || [];
                for (let i = arr.length - 1; i >= 0; i--) {
                  if (String(arr[i].message || '').indexOf('<libido_status>') >= 0) { target = arr[i].message_id; break; }
                }
                if (target == null) target = last;
              }
              if (target != null) {
                let curMsg = '';
                try { const a = thFn('getChatMessages')(target) || []; if (a.length) curMsg = String(a[0].message || ''); } catch (e) {}
                const stripped = curMsg.replace(/[\s]*<libido_status>[\s\S]*?<\/libido_status>[\s]*/gi, '');
                const newMsg = (stripped ? stripped.trimEnd() + '\n\n' : '') + newText;
                await thFn('setChatMessages')([{ message_id: target, message: newMsg }], { refresh: 'affected' });
              }
              // 更新聊天级上一次状态栏 + 手改锁定
              setLastStatus(newText);
              const s = loadSettings();
              s.manual_lock_remaining = lock;
              saveSettings(s);
              log('info', '已保存手动编辑的状态栏（锁定 ' + lock + ' 轮）');
              toastr.success('已保存并锁定 ' + lock + ' 轮');
              refreshPreviews();
              popup.complete(1);
            } catch (e2) {
              log('error', '保存手动编辑失败: ' + String(e2 && e2.stack || e2));
              toastr.error('保存失败，详情见日志');
            }
          });
        },
      });
    } catch (e3) {
      log('error', '打开编辑弹窗失败: ' + String(e3 && e3.stack || e3));
      toastr.error('打开编辑弹窗失败');
    }
  });

  // B：查看历史 / 回滚
  $panel.on('click', '[data-sbh="feat-history"]', function () {
    const h = getHistory();
    const $c = $('<div style="display:flex;flex-direction:column;gap:8px;min-width:420px">');
    $c.append($('<div style="font-weight:600">').text('状态栏历史（' + h.length + ' 条，点击「回滚」恢复为当前状态栏）'));
    if (!h.length) {
      $c.append($('<div style="text-align:center;padding:14px;opacity:.6">').text('暂无历史记录（开启功能 B 后每次生成会保存快照）。'));
    } else {
      const $wrap = $('<div style="max-height:340px;overflow:auto;display:flex;flex-direction:column;gap:4px">');
      h.slice().reverse().forEach(function (item, i) {
        const idx = h.length - 1 - i; // 原始索引
        const sum = (item.stats && Object.keys(item.stats).length) ? Object.keys(item.stats).join(', ') : '（未解析到数值）';
        const $row = $('<div style="border:1px solid var(--SmartThemeBorderColor);border-radius:8px;padding:6px 8px;background:var(--SmartThemeBlurTintColor);display:flex;align-items:center;gap:8px">');
        $row.append($('<div style="flex:1;min-width:0;font-size:12px">').text('[' + item.time + '] 楼#' + item.floor + ' · ' + (item.reason || '') + ' · ' + sum));
        $row.append($('<button class="menu_button" data-sbh-hist="view" data-idx="' + idx + '" style="font-size:11px;padding:2px 6px">查看</button>'));
        $row.append($('<button class="menu_button" data-sbh-hist="roll" data-idx="' + idx + '" style="font-size:11px;padding:2px 6px">回滚</button>'));
        $wrap.append($row);
      });
      $c.append($wrap);
    }
    const $f2 = $('<div style="display:flex;justify-content:flex-end"><button class="menu_button" data-sbh-hist="close">关闭</button></div>');
    $c.append($f2);
    try {
      SillyTavern.callGenericPopup($c, SillyTavern.POPUP_TYPE.DISPLAY, undefined, {
        okButton: false, cancelButton: false, wide: true, allowVerticalScrolling: true,
        onOpen: function (popup) {
          $c.find('[data-sbh-hist="view"]').on('click', function () {
            const item = h[$(this).data('idx')];
            if (!item) return;
            popup.complete(1);
            try { toastr.info('原始状态栏（复制用）已写入剪贴板'); } catch (e) {}
            const th = TH();
            if (th && th.builtin && typeof th.builtin.copyText === 'function') th.builtin.copyText(item.text || '');
            else if (navigator && navigator.clipboard) navigator.clipboard.writeText(item.text || '');
            else prompt('状态栏原文:', item.text || '');
          });
          $c.find('[data-sbh-hist="roll"]').on('click', function () {
            const item = h[$(this).data('idx')];
            if (!item) return;
            popup.complete(1);
            setLastStatus(item.text || '');
            try {
              const last = thFn('getLastMessageId')();
              let target = null;
              if (last != null && last >= 0) {
                const arr = thFn('getChatMessages')(last) || [];
                for (let j = arr.length - 1; j >= 0; j--) {
                  if (String(arr[j].message || '').indexOf('<libido_status>') >= 0) { target = arr[j].message_id; break; }
                }
                if (target == null) target = last;
              }
              if (target != null) {
                let curMsg = '';
                try { const a = thFn('getChatMessages')(target) || []; if (a.length) curMsg = String(a[0].message || ''); } catch (e) {}
                const stripped = curMsg.replace(/[\s]*<libido_status>[\s\S]*?<\/libido_status>[\s]*/gi, '');
                const newMsg = (stripped ? stripped.trimEnd() + '\n\n' : '') + item.text;
                thFn('setChatMessages')([{ message_id: target, message: newMsg }], { refresh: 'affected' });
              }
            } catch (e) {}
            log('info', '已回滚状态栏到 ' + item.time);
            toastr.success('已回滚到该时刻状态栏');
            refreshPreviews();
          });
          $c.find('[data-sbh-hist="close"]').on('click', function () { popup.complete(1); });
        },
      });
    } catch (e4) {
      log('error', '打开历史弹窗失败: ' + String(e4 && e4.stack || e4));
      toastr.error('打开历史弹窗失败');
    }
  });

  renderPanel();
  log('success', '设置面板已挂载到扩展设置区（#extensions_settings2）');
}

/** 填充面板控件当前值 */
function renderPanel() {
  const $panel = $('#sbh-drawer');
  if (!$panel.length) return;
  $panel.find('[data-sbh="enabled"]').prop('checked', !!cfg.enabled);
  $panel.find('[data-sbh="mode"]').prop('checked', false);
  $panel.find('[data-sbh="mode"][value="' + (cfg.api_mode === 'custom' ? 'custom' : 'tavern') + '"]').prop('checked', true);
  $panel.find('[data-sbh="format"]').val(cfg.format_text || '');
  $panel.find('[data-sbh="jailbreak"]').val(cfg.jailbreak || '');
  $panel.find('[data-sbh="rules"]').val(cfg.rules_text || '');
  $panel.find('[data-sbh="gen-rules"]').val(cfg.gen_rules_text || '');
  // 生成参数（高级）
  $panel.find('[data-sbh="chat-depth"]').val(String(Number(cfg.chat_depth) || 4));
  const gp = cfg.gen_params || {};
  $panel.find('[data-sbh="max-tokens"]').val(gp.max_tokens || 40000);
  // 「不限制最大 token」默认勾选（旧配置无此字段时视为勾选），勾选时输入框置灰
  const nlTok = gp.no_limit_tokens !== false;
  $panel.find('[data-sbh="no-limit-tokens"]').prop('checked', nlTok);
  $panel.find('[data-sbh="max-tokens"]').prop('disabled', nlTok);
  const tp = gp.temperature;
  $panel.find('[data-sbh="temperature"]').val(tp === '' || tp === null || tp === undefined ? '' : Number(tp));
  $panel.find('[data-sbh="max-send-chars"]').val(Number(cfg.max_send_chars) || 50000);
  // 「不限制最大发送字数」默认勾选（旧配置无此字段时视为勾选），勾选时输入框置灰
  const nlChars = cfg.no_limit_send_chars !== false;
  $panel.find('[data-sbh="no-limit-chars"]').prop('checked', nlChars);
  $panel.find('[data-sbh="max-send-chars"]').prop('disabled', nlChars);
  // 不发送所有世界书
  $panel.find('[data-sbh="wb-none"]').prop('checked', !!cfg.wb_none);
  // 增强功能开关回填
  const feat = cfg.features || {};
  ['sync_vars', 'history', 'retry', 'manual_edit', 'group_chat', 'share_cfg'].forEach(function (k) {
    $panel.find('[data-sbh="feat-' + k + '"]').prop('checked', !!feat[k]);
  });
  $panel.find('[data-sbh="retry-count"]').val(Number(cfg.retry_count) >= 0 ? cfg.retry_count : 2);
  $panel.find('[data-sbh="manual-locks"]').val(Number(cfg.manual_edit_locks) >= 0 ? cfg.manual_edit_locks : 3);
  renderProfiles();
  renderPromptOrder();
  renderWb();
  renderLast();
}

/** 渲染「提示词顺序」列表：每行 = 段名 + ↑ ↓ 按钮（上下限置灰），顺序来自 cfg.prompt_order */
function renderPromptOrder() {
  const $box = $('#sbh-drawer [data-sbh="prompt-order-list"]');
  if (!$box.length) return;
  const order = cfg.prompt_order && cfg.prompt_order.length ? cfg.prompt_order.slice() : SBH_PROMPT_ORDER_DEFAULT.slice();
  const segs = buildPromptSegments(cfg, '', [], '');
  $box.empty();
  order.forEach(function (key, i) {
    const label = segs[key] ? segs[key].label : key;
    const $row = $('<div style="display:flex;align-items:center;gap:8px;border:1px solid var(--SmartThemeBorderColor);border-radius:8px;padding:5px 8px;background:var(--SmartThemeBlurTintColor)">').attr('data-po-i', i);
    $row.append($('<span style="flex:0 0 22px;font-size:11px;opacity:.55;font-weight:700">').text((i + 1) + '.'));
    $row.append($('<span style="flex:1;font-size:13px;font-weight:700">').text(label));
    $row.append($('<input type="button" class="menu_button" data-sbh="po-move" data-dir="-1" value="↑" style="font-size:12px;padding:1px 8px"' + (i === 0 ? ' disabled' : '') + '>'));
    $row.append($('<input type="button" class="menu_button" data-sbh="po-move" data-dir="1" value="↓" style="font-size:12px;padding:1px 8px"' + (i === order.length - 1 ? ' disabled' : '') + '>'));
    $box.append($row);
  });
}

/** 渲染独立配置列表（DOM 构建，用户数据全部用 .val()/.text()，无 innerHTML 注入） */
function renderProfiles() {
  const $box = $('#sbh-drawer [data-sbh="profiles"]');
  if (!$box.length) return;
  $box.empty();
  if (!cfg.profiles.length) {
    $box.append($('<div style="font-size:12px;opacity:.7">').text('暂无独立配置，点击「+ 新增配置」添加。'));
    return;
  }
  cfg.profiles.forEach(function (p, i) {
    const $row = $('<div class="sbh-prof" style="border:1px solid var(--SmartThemeBorderColor);border-radius:8px;padding:6px;margin:6px 0;background:var(--SmartThemeBlurTintColor)">').data('i', i);

    const $r1 = $('<div class="flex-container" style="flex-wrap:wrap">');
    const $active = $('<input type="radio" name="sbh-prof-active" data-sbh="p-active">');
    if (p.enabled) $active.prop('checked', true);
    $r1.append($('<label class="flex-container">').append($active).append($('<span>').text('启用')));
    $r1.append($('<input type="text" class="text_pole" data-sbh="p-name" placeholder="名称" style="flex:1 1 120px">').val(p.name));
    $r1.append($('<input type="button" class="menu_button" data-sbh="test-prof" value="测试连接">'));
    $r1.append($('<input type="button" class="menu_button" data-sbh="del-prof" value="删除">'));

    const $r2 = $('<div class="flex-container" style="flex-wrap:wrap">');
    $r2.append($('<input type="text" class="text_pole" data-sbh="p-apiurl" placeholder="apiurl 如 https://api.openai.com/v1" style="flex:2 1 200px">').val(p.apiurl));
    $r2.append($('<input type="password" class="text_pole" data-sbh="p-key" placeholder="API key" style="flex:1 1 150px">').val(p.key));

    const $r3 = $('<div class="flex-container" style="flex-wrap:wrap">');
    $r3.append($('<input type="text" class="text_pole" data-sbh="p-model" placeholder="model 如 gpt-4o-mini" style="flex:1 1 140px">').val(p.model));
    // API源：下拉选择（OpenAI 兼容接口选 openai，DeepSeek/多数国内中转通用）
    const $src = $('<select class="text_pole" data-sbh="p-source" style="flex:0 1 110px" title="API源：OpenAI 兼容接口选 openai（DeepSeek/多数国内中转通用）；特殊格式接口选 custom 等">');
    const srcVal = String(p.source || 'openai').trim() || 'openai';
    const srcOptions = ['openai', 'deepseek', 'claude', 'mistralai', 'makersuite', 'vertexai', 'xai', 'zai', 'moonshot', 'custom'];
    const srcAll = srcOptions.slice();
    if (srcAll.indexOf(srcVal) < 0) srcAll.unshift(srcVal); // 保留旧的未知值
    srcAll.forEach(function (s) {
      const $o = $('<option>').val(s).text(s);
      if (s === srcVal) $o.prop('selected', true);
      $src.append($o);
    });
    $r3.append($src);
    $r3.append($('<input type="button" class="menu_button" data-sbh="models-prof" value="获取模型">'));
    $r3.append($('<span data-sbh="p-result" style="font-size:12px;min-width:120px">'));

    const $r4 = $('<div class="flex-container" style="flex-wrap:wrap">');
    $r4.append($('<select data-sbh="p-models" class="text_pole" style="display:none;flex:1 1 200px">'));

    $row.append($r1, $r2, $r3, $r4);
    $box.append($row);
  });
}

/** 世界书 chip 按钮行（悬浮按钮样式）；data-sbh 放在 × 上，点击 × 触发排除/取消排除 */
function wbChip(name, note, action, actionTitle, isExcluded) {
  const $chip = $('<span style="display:inline-flex;align-items:center;gap:5px;padding:3px 9px;border:1px solid ' + (isExcluded ? 'var(--SmartThemeQuoteColor)' : 'var(--SmartThemeBorderColor)') + ';border-radius:14px;background:' + (isExcluded ? 'rgba(207,102,138,.12)' : 'var(--SmartThemeBlurTintColor)') + ';cursor:default;margin:2px;font-size:12.5px;font-weight:600;white-space:nowrap">');
  $chip.append($('<span style="max-width:180px;overflow:hidden;text-overflow:ellipsis">').text(name));
  if (note) $chip.append($('<span style="font-size:11px;opacity:.65">').text(note));
  const $x = $('<span class="sbh-x" style="color:#c0392b;font-weight:700;font-size:14px;padding:0 4px;border-radius:50%;cursor:pointer">').text('×').attr('title', actionTitle).data('name', name);
  if (action) $x.attr('data-sbh', action);
  $chip.append($x);
  return $chip;
}

/** 渲染世界书列表：已激活（可 × 排除）+ 已排除（可 × 取消排除），悬浮按钮样式。
    「状态栏助手-最近状态栏」为插件内置注入书，固定置顶显示、不可移除、不受"不发送所有世界书"影响 */
function renderWb() {
  const $active = $('#sbh-drawer [data-sbh="wb-active"]');
  const $excluded = $('#sbh-drawer [data-sbh="wb-excluded"]');
  const $tip = $('#sbh-drawer [data-sbh="wb-none-tip"]');
  const $noneBox = $('#sbh-drawer .sbh-wb-none-box');
  if (!$active.length || !$excluded.length) return;
  const excluded = cfg.excluded_worldbooks || {};
  const wbNone = !!cfg.wb_none;
  $active.empty();
  $excluded.empty();

  // 「不发送所有世界书」勾选时高亮关联框
  if ($noneBox.length) {
    if (wbNone) $noneBox.css({ 'border-color': 'var(--SmartThemeQuoteColor)', 'background': 'rgba(207,102,138,.08)' });
    else $noneBox.css({ 'border-color': '', 'background': '' });
  }

  if ($tip.length) {
    $tip.text(wbNone ? '当前已开启：世界书资料已跳过。' : '');
  }

  if (wbNone) {
    $active.append($('<span style="font-size:12px;opacity:.7">').text('已开启「不发送所有世界书」，下方列表暂时隐藏。'));
  } else {
    let active = [];
    try { active = getActiveWorldbooksSync(); } catch (e) {}
    const activeNotExcluded = active.filter(w => !excluded[w.name]);
    if (!activeNotExcluded.length) {
      $active.append($('<span style="font-size:12px;opacity:.7">').text('无（当前没有会发送的世界书，或全部已不发送）。'));
    } else {
      const $wrap = $('<div style="display:flex;flex-wrap:wrap;gap:2px">');
      activeNotExcluded.forEach(function (w) {
        $wrap.append(wbChip(w.name, w.source || '', 'wb-exclude', '不发送这本书', false));
      });
      $active.append($wrap);
    }
  }

  const excludedNames = Object.keys(excluded).filter(n => excluded[n]);
  if (!excludedNames.length) {
    $excluded.append($('<span style="font-size:12px;opacity:.7">').text('暂无。'));
  } else {
    const $wrap = $('<div style="display:flex;flex-wrap:wrap;gap:2px">');
    excludedNames.forEach(function (n) {
      $wrap.append(wbChip(n, '', 'wb-unexclude', '恢复发送', true));
    });
    $excluded.append($wrap);
  }
}

/** 「选择排除世界书」弹窗：搜索 + 全部世界书勾选（参照官方弹窗模式） */
function openPickExcluded() {
  const allNames = getWorldbookNamesSync();
  const excluded = cfg.excluded_worldbooks || {};

  const $c = $('<div style="display:flex;flex-direction:column;gap:8px;min-width:320px">');
  $c.append($('<div style="font-weight:600">').text('选择不发送的世界书（勾选 = 不发送；搜索可快速过滤）'));
  const $search = $('<input class="text_pole" type="text" placeholder="搜索世界书名称…">');
  $c.append($search);
  const $list = $('<div style="max-height:320px;overflow:auto;display:flex;flex-direction:column;gap:2px;border:1px solid var(--SmartThemeBorderColor);border-radius:6px;padding:6px">');
  $c.append($list);
  const $foot = $('<div style="display:flex;justify-content:flex-end;gap:8px">')
    .append($('<button class="menu_button" data-sbh-pop="cancel">取消</button>'))
    .append($('<button class="menu_button" data-sbh-pop="ok">确定</button>'));
  $c.append($foot);

  function buildList(filter) {
    $list.empty();
    if (!allNames.length) {
      $list.append($('<span style="font-size:12px;opacity:.7">').text('未读取到世界书列表。'));
      return;
    }
    const f = (filter || '').toLowerCase();
    allNames.forEach(function (n) {
      if (f && n.toLowerCase().indexOf(f) < 0) return;
      const $row = $('<label style="display:flex;align-items:center;gap:6px;cursor:pointer">');
      const $cb = $('<input type="checkbox">').val(n);
      if (excluded[n]) $cb.prop('checked', true);
      $row.append($cb);
      $row.append($('<span>').text(n));
      $list.append($row);
    });
  }
  buildList('');
  $search.on('input', function () { buildList($(this).val() || ''); });

  try {
    SillyTavern.callGenericPopup($c, SillyTavern.POPUP_TYPE.DISPLAY, undefined, {
      okButton: false,
      cancelButton: false,
      wide: true,
      allowVerticalScrolling: true,
      onOpen: function (popup) {
        $c.find('[data-sbh-pop="ok"]').on('click', function () {
          const ex = {};
          $c.find('input[type=checkbox]:checked').each(function () {
            const n = $(this).val();
            if (n) ex[n] = true;
          });
          cfg.excluded_worldbooks = ex;
          renderWb();
          refreshPreviews();
          try { toastr.success('已更新不发送列表'); } catch (e) {}
          popup.complete(1);
        });
        $c.find('[data-sbh-pop="cancel"]').on('click', function () { popup.complete(1); });
      },
    });
  } catch (e) {
    log('error', '打开选择排除世界书弹窗失败: ' + String(e && e.stack || e));
    try { toastr.error('弹窗打开失败: ' + String(e && e.message || e)); } catch (e2) {}
  }
}

/** 刷新三个只读预览框（发送内容预览，固定大小） */
async function refreshPreviews() {
  const $wb = $('#sbh-drawer [data-sbh="preview-wb"]');
  const $chat = $('#sbh-drawer [data-sbh="preview-chat"]');
  const $last = $('#sbh-drawer [data-sbh="preview-last"]');
  if (!$wb.length || !$chat.length || !$last.length) return;
  // 资源优化：面板折叠/隐藏时跳过预览刷新（世界书内容读取是异步的，避免后台空转）；
  // 展开时会通过 inline-drawer-toggle 事件 / 刷新按钮 / 手动调用重新刷新
  try {
    const $body = $('#sbh-drawer .inline-drawer-content');
    if ($body.length && !$body.is(':visible')) return;
  } catch (e) {}

  // 最近对话（同步）
  const chat = getRecentChat(4);
  $chat.val(chat.length ? chat.join('\n') : '（暂无对话）');

  // 上一次状态栏数据（同步，聊天级隔离）
  const lastStatus = getLastStatus();
  $last.val(lastStatus || '（暂无，首次生成时会以「无上一次状态栏」发送）');

  // 当前激活世界书资料（异步读取内容）
  const c = cfg || loadSettings();
  if (c.wb_none) {
    $wb.val('已开启「不发送所有世界书」：本段不会发送。');
  } else {
    $wb.val('正在读取世界书内容…');
    try {
      const t = await collectWorldbookInfo(c);
      $wb.val(t || '（当前没有可发送的世界书资料）');
    } catch (e) {
      $wb.val('读取失败: ' + String(e && e.message || e));
    }
  }
}

/** 更新"上次运行"显示 */
function renderLast() {
  const $el = $('#sbh-drawer [data-sbh="last"]');
  if (!$el.length) return;
  if (!cfg.last_run) { $el.text('上次运行：暂无记录'); return; }
  const r = cfg.last_run;
  $el.text('上次运行：' + r.time + ' · ' + (r.ok ? '成功' : '失败') + ' · 耗时 ' + (r.ms / 1000).toFixed(1) + ' 秒 · 触发：' + (r.reason || '') + (r.err ? ' · 错误：' + r.err : ''));
  renderHist5(); // 联动刷新「最近 5 次」历史列表
}

/** 渲染「最近 5 次生成的状态栏」列表（聊天变量持久化；楼层只留最新 1 份） */
function renderHist5() {
  const $box = $('#sbh-drawer [data-sbh="hist5"]');
  if (!$box.length) return;
  const h = getStatusHistory();
  $box.empty();
  if (!h.length) {
    $box.append($('<div style="font-size:12px;opacity:.7">').text('暂无记录（每次成功生成状态栏后自动保存，最多 5 份）。'));
    return;
  }
  h.slice().reverse().forEach(function (item) {
    const txt = String(item.text || '');
    const $row = $('<div style="border:1px dashed var(--SmartThemeBorderColor);border-radius:6px;padding:4px 7px;margin:3px 0;background:var(--SmartThemeBlurTintColor)">');
    $row.append($('<div style="font-size:11px;opacity:.7;font-weight:600">').text('[' + (item.time || '') + '] 楼层#' + (item.floor != null ? item.floor : '-') + ' · ' + (item.reason || '')));
    $row.append($('<div style="font-size:11.5px;white-space:pre-wrap;word-break:break-all;max-height:120px;overflow:auto;margin-top:2px;opacity:.85">').text(txt.slice(0, 400) + (txt.length > 400 ? ' …' : '')));
    $box.append($row);
  });
}

/** 更新"生成状态"显示 */
function setRunStatus(msg, color) {
  const $el = $('#sbh-drawer [data-sbh="run-status"]');
  if (!$el.length) return;
  $el.text(msg || '');
  if (color) $el.css('color', color); else $el.css('color', '');
}

/** 展开设置面板（旧按钮保留兼容） */
function openSettings() {
  log('info', '收到「状态栏助手设置」按钮点击，展开设置面板');
  const $d = $('#sbh-drawer');
  if ($d.length) {
    $d.find('.inline-drawer-content').show();
    renderWb();
    refreshPreviews();
    try { $d[0].scrollIntoView({ behavior: 'smooth', block: 'start' }); } catch (e) {}
  } else {
    initPanel();
  }
}

/* ==================== 日志弹窗（popup + jQuery 对象 + onOpen，参照官方扩写脚本） ==================== */

const levelColor = { error: '#c0392b', warn: '#b7791f', success: '#1f9d55', info: '' };

function openLogs() {
  log('info', '收到「查看日志」按钮点击');
  try { toastr.info('状态栏助手：正在打开日志…'); } catch (e) {}
  const logs = getLogs();

  const $content = $('<div style="max-width:760px">');
  $content.append($('<div style="font-weight:700;margin:0 0 8px">').text('状态栏助手 · 日志（共 ' + logs.length + ' 条，点击条目展开/折叠）'));

  // 最近一次发送的提示词（保存在配置中，持久化，不受日志 200 条上限影响）
  try {
    const lp = (loadSettings() || {}).last_prompt;
    if (lp && lp.length) {
      const $lp = $('<details style="border:1px solid var(--SmartThemeQuoteColor);border-radius:8px;margin:0 0 8px;background:rgba(207,102,138,.06)">');
      const $sum = $('<summary style="cursor:pointer;padding:6px 10px;font-weight:700;color:var(--SmartThemeQuoteColor);list-style:none;user-select:none;display:flex;align-items:center;gap:10px">');
      $sum.append($('<span style="flex:1">').text('最近一次发送的提示词（' + lp.length + ' 段，点击展开）'));
      const $copy = $('<span class="sbh-link" title="复制全部提示词到剪贴板">📋 复制全部</span>');
      $sum.append($copy);
      $lp.append($sum);
      lp.forEach(function (p, i) {
        // 完整显示：不设 max-height，内容多时依赖弹窗滚动
        $lp.append($('<pre style="margin:0;padding:4px 10px;border-top:1px dashed var(--SmartThemeBorderColor);white-space:pre-wrap;word-break:break-all;font-size:12px">').text('【第 ' + (i + 1) + ' 段 · ' + p.role + '】\n' + p.content));
      });
      $content.append($lp);
      // 复制全部提示词
      $copy.on('click', function () {
        const txt = lp.map(function (p, i) { return '【第 ' + (i + 1) + ' 段 · ' + p.role + '】\n' + p.content; }).join('\n\n');
        const th = TH();
        if (th && th.builtin && typeof th.builtin.copyText === 'function') {
          th.builtin.copyText(txt);
          toastr.success('已复制全部提示词（' + lp.length + ' 段）');
        } else if (navigator && navigator.clipboard && navigator.clipboard.writeText) {
          navigator.clipboard.writeText(txt).then(function () { toastr.success('已复制全部提示词（' + lp.length + ' 段）'); }, function () { toastr.error('复制失败，请手动复制'); });
        } else {
          prompt('复制以下提示词:', txt);
        }
      });
    }
  } catch (e) {}

  if (!logs.length) {
    $content.append($('<div style="text-align:center;padding:16px;opacity:.6">').text('暂无日志。'));
  } else {
    logs.slice().reverse().forEach(function (l) {
      const color = levelColor[l.level] || '';
      const head = String(l.content == null ? '' : l.content);
      const $d = $('<details style="border:1px solid var(--SmartThemeBorderColor);border-radius:6px;margin:3px 0;background:var(--SmartThemeBlurTintColor)">');
      const $sum = $('<summary style="cursor:pointer;padding:4px 8px;font-weight:600;list-style:none">').text('[' + l.time + '] ' + l.level + ' · ' + head.slice(0, 60));
      if (color) $sum.css('color', color);
      $d.append($sum);
      $d.append($('<pre style="margin:0;padding:6px 8px;border-top:1px dashed var(--SmartThemeBorderColor);white-space:pre-wrap;word-break:break-all;max-height:300px;overflow:auto;font-size:12px">').text(head));
      $content.append($d);
    });
  }

  const $foot = $('<div style="text-align:right;margin-top:8px">')
    .append($('<input type="button" class="menu_button" data-sbh-log="copy" value="复制全部日志">'))
    .append(' ')
    .append($('<input type="button" class="menu_button" data-sbh-log="clear" value="清空日志">'))
    .append(' ')
    .append($('<input type="button" class="menu_button" data-sbh-log="close" value="关闭">'));
  $content.append($foot);

  try {
    SillyTavern.callGenericPopup($content, SillyTavern.POPUP_TYPE.DISPLAY, undefined, {
      okButton: false,
      cancelButton: false,
      wide: true,
      allowVerticalScrolling: true,
      onOpen: function (popup) {
        $content.find('[data-sbh-log="copy"]').on('click', function () {
          const text = logs.map(function (l) { return '[' + l.time + '] [' + l.level + '] ' + l.content; }).join('\n');
          const th = TH();
          if (th && th.builtin && typeof th.builtin.copyText === 'function') {
            th.builtin.copyText(text);
            toastr.success('已复制 ' + logs.length + ' 条日志');
          } else if (navigator && navigator.clipboard && navigator.clipboard.writeText) {
            navigator.clipboard.writeText(text).then(function () { toastr.success('已复制 ' + logs.length + ' 条日志'); }, function () { toastr.error('复制失败，请手动复制'); });
          } else {
            prompt('复制以下日志:', text);
          }
        });
        $content.find('[data-sbh-log="clear"]').on('click', function () {
          clearLogs();
          toastr.success('日志已清空');
          popup.complete(1);
        });
        $content.find('[data-sbh-log="close"]').on('click', function () { popup.complete(1); });
      },
    });
    log('info', '日志面板已打开');
  } catch (e) {
    log('error', '日志面板打开失败: ' + String(e && e.stack || e));
    try { toastr.error('日志面板打开失败: ' + String(e && e.message || e)); } catch (e2) {}
  }
}

/* ==================== 事件监听与初始化 ==================== */

function onMessageReceived(message_id, type) {
  try {
    if (type !== 'normal' && type !== 'regenerate') return; // 只响应发送正文 / 重新生成
    const s = loadSettings();
    if (!s.enabled) return;
    // 功能 D：手改锁定——自动触发生成时，若当前聊天的"上次状态栏"被手动编辑过且在锁定轮数内，
    // 则跳过本次自动覆盖（保留手改内容）；保护期过后恢复自动更新。
    if (s.features && s.features.manual_edit) {
      try {
        const lock = Number(s.manual_lock_remaining) || 0;
        if (lock > 0) {
          const remain = lock - 1;
          s.manual_lock_remaining = remain;
          saveSettings(s);
          log('info', '手改锁定中，跳过本次自动覆盖（剩余 ' + remain + ' 次触发）');
          try { toastr.info('状态栏被手动锁定，本次自动更新已跳过（剩余 ' + remain + ' 次）'); } catch (e3) {}
          return;
        }
      } catch (e4) {}
    }
    log('info', '收到正文生成事件 type=' + type + ' (楼层#' + message_id + ')，自动触发状态栏生成（目标楼层 #' + message_id + '）');
    runStatusBar('自动触发(' + type + ')', message_id);
  } catch (e) {
    log('error', '事件处理出错: ' + String(e && e.stack || e));
  }
}

/** 绑定面板按钮事件：优先新版 getButtonEvent+eventOn，失败回退旧版 eventOnButton */
function bindButton(name, fn) {
  if (typeof getButtonEvent === 'function' && typeof eventOn === 'function') {
    try {
      const ev = getButtonEvent(name);
      eventOn(ev, fn);
      log('success', '按钮事件绑定成功: ' + name + ' → ' + ev);
      return true;
    } catch (e1) {
      log('warn', 'getButtonEvent 方式绑定失败 (' + name + '): ' + String(e1 && e1.message || e1) + '，尝试旧版 eventOnButton');
    }
  }
  if (typeof eventOnButton === 'function') {
    try {
      eventOnButton(name, fn);
      log('success', '按钮事件绑定成功(旧版 eventOnButton): ' + name);
      return true;
    } catch (e2) {
      log('error', 'eventOnButton 绑定失败 (' + name + '): ' + String(e2 && e2.message || e2));
    }
  } else {
    log('error', '当前环境没有可用的按钮事件绑定 API (getButtonEvent/eventOnButton 均不可用)');
  }
  try { toastr.error('按钮「' + name + '」事件绑定失败，详见「查看日志」'); } catch (e3) {}
  return false;
}

function init() {
  try {
    // 记录运行环境（方便排查）
    let iframeName = '未知';
    try { iframeName = getIframeName(); } catch (e) {}
    log('info', '脚本初始化。iframe=' + iframeName
      + '，getButtonEvent=' + (typeof getButtonEvent)
      + '，eventOnButton=' + (typeof eventOnButton)
      + '，SillyTavern=' + (typeof SillyTavern)
      + '，callGenericPopup=' + (typeof SillyTavern !== 'undefined' ? typeof SillyTavern.callGenericPopup : 'n/a'));

    if (typeof eventOn !== 'function') {
      log('error', '未检测到 eventOn，脚本可能运行在非酒馆助手环境');
      try { toastr.error('状态栏助手：未检测到酒馆助手事件接口，脚本未启动'); } catch (e) {}
      return;
    }

    try { eventOn(tavern_events.MESSAGE_RECEIVED, onMessageReceived); } catch (e) {
      log('error', '监听 MESSAGE_RECEIVED 失败: ' + String(e && e.message || e));
    }
    try { eventOn(tavern_events.WORLD_INFO_ACTIVATED, onWorldInfoActivated); } catch (e) {
      log('warn', '监听 WORLD_INFO_ACTIVATED 失败: ' + String(e && e.message || e));
    }

    // 角色卡 / 聊天切换时自动刷新世界书列表与发送内容预览
    try {
      eventOn(tavern_events.CHAT_CHANGED, function () {
        log('info', '检测到角色卡/聊天切换，自动刷新世界书列表与预览');
        try {
          cfg = loadSettings();
          renderWb();
          renderLast();
          refreshPreviews();
        } catch (e2) {
          log('warn', '角色切换刷新失败: ' + String(e2 && e2.message || e2));
        }
      });
    } catch (e) {
      log('warn', '监听 CHAT_CHANGED 失败: ' + String(e && e.message || e));
    }

    // 确保按钮存在（幂等）：设置已集成进扩展区面板，输入框旁保留两个操作按钮
    // （手动生成状态栏 = 发送上一次状态栏；关闭自动生成开关也能用。重新生成状态栏在面板内）
    try {
      replaceScriptButtons([
        { name: '手动生成状态栏', visible: true },
        { name: '修正标签间距', visible: true },
        { name: '查看日志', visible: true },
      ]);
    } catch (e) {
      log('warn', 'replaceScriptButtons 失败: ' + String(e && e.message || e));
    }

    bindButton('手动生成状态栏', manualStatusBar);
    bindButton('修正标签间距', fixStatusBar);
    bindButton('查看日志', openLogs);

    // 按钮自检（诊断）：核对 QR 栏实际渲染的按钮与脚本绑定的事件名是否一致。
    // 按钮点击链路：QR 栏按钮点击 emit(按钮id)，脚本 iframe 用 eventOn(getButtonEvent(按钮名)) 监听同一 id；
    // 若 QR 栏按钮名 ≠ 脚本里绑定的按钮名，或脚本 iframe 未重载最新内容，则点击无人接听（按钮点不开）。
    try {
      const getAB = thFn('getAllEnabledScriptButtons');
      if (getAB) {
        const all = getAB() || {};
        const mine = all[SBH_SID] || [];
        if (mine.length) {
          log('info', 'QR 栏按钮对照（脚本 ' + SBH_SID + '）：' + mine.map(function (b) { return b.button_name + '[' + b.button_id + ']'; }).join('、'));
          mine.forEach(function (b) {
            const ev = (typeof getButtonEvent === 'function') ? getButtonEvent(b.button_name) : '';
            if (ev !== b.button_id) {
              log('warn', '按钮事件不匹配：QR 栏 ' + b.button_name + ' 的 id=' + b.button_id + '，脚本绑定的事件=' + ev + '。请刷新页面让脚本 iframe 重载最新内容。');
            }
          });
        } else {
          log('warn', 'QR 栏未找到本脚本按钮（脚本可能未启用，或按钮被其他脚本覆盖）。');
        }
      }
    } catch (e) {
      log('warn', '按钮自检失败: ' + String(e && e.message || e));
    }

    // 功能 A：注册聊天变量结构（变量管理器校验，防手改错类型）
    try { registerStatSchema(); } catch (e) {
      log('warn', '注册变量结构失败: ' + String(e && e.message || e));
    }

    // 脚本销毁（禁用/刷新页面）时清理挂到父页面的面板 DOM
    try {
      $(window).on('pagehide', function () {
        try { $('#sbh-drawer').remove(); } catch (e) {}
      });
    } catch (e) {}

    log('success', '状态栏助手已加载。设置/重新生成/日志全部集成在「扩展程序 → 扩展设置 → 状态栏助手」面板；输入框旁保留「手动生成状态栏」「修正标签间距」「查看日志」三个快捷按钮。');
  } catch (e) {
    log('error', '初始化失败: ' + String(e && e.stack || e));
    try { toastr.error('状态栏助手初始化失败: ' + String(e && e.message || e)); } catch (e2) {}
  }
}

/* 入口：等酒馆页面 DOM ready 后再挂面板与绑定（参照官方扩写脚本的写法） */
$(function () {
  try {
    initPanel();
    refreshPreviews();
  } catch (e) {
    try { log('error', '设置面板初始化失败: ' + String(e && e.stack || e)); } catch (e2) {}
